const majorDeepDetails = {
  'major-0': {overview:'一位年轻旅人站在高崖边缘，目光望向远方。他轻装上路，阳光照耀，身旁的小狗既陪伴又提醒。整幅画停留在“迈出第一步之前”的瞬间，强调自由、信任与未知。', symbols:[['人物与姿态','年轻人身体轻盈、头部微抬，说明注意力朝向理想与未来，而不是脚下的现实风险。'],['白玫瑰','白色象征纯净，玫瑰象征欲望与生命；合在一起表示动机单纯、尚未被经验复杂化。'],['小狗','代表本能、忠诚与现实提醒。它既像伙伴，也像在警告愚人留意悬崖。'],['悬崖','象征旧经验无法覆盖的未知领域。它既是风险，也是离开熟悉世界的门槛。'],['行囊与长杖','行囊很小，表示只带着必要经验；长杖则像旅途中的意志与支撑。'],['高山与太阳','高山预示未来挑战，明亮太阳则说明生命力与信任仍占主导。']], colors:'黄色与白色占主导：黄色象征意识、乐观与生命力；白色象征初心与开放。远处冷色山峰提醒，旅程仍包含现实考验。'},
  'major-1': {overview:'魔术师站在花园中，一手指天、一手指地，桌面摆着四种牌组法器。他不是凭空创造，而是把已有资源组织起来，将意志转化为现实。', symbols:[['人物与手势','右手举杖指向天空，左手指向大地，形成“如其在上，如其在下”的姿态。'],['四件法器','权杖、圣杯、宝剑、星币对应火、水、风、土，说明行动所需资源已经齐备。'],['无限符号','头顶的横向八字象征持续流动的能量、专注与潜能。'],['蛇形腰带','蛇咬尾巴代表循环、自我更新与能量不灭。'],['红玫瑰与白百合','红色代表欲望与行动，白色代表纯净与精神目标，两者需要合作。']], colors:'红色长袍强调意志、行动与热情；白色内衣提示动机需要保持清晰。花园中的红白花朵重复了“欲望与纯粹”的双重主题。'},
  'major-2': {overview:'女祭司静坐在黑白双柱之间，背后是石榴帷幕，怀中卷轴半遮半露。她不主动解释世界，而是守护那些必须通过安静、时间与直觉才能理解的知识。', symbols:[['人物与姿态','她正面端坐、表情克制，没有明显动作，表示力量来自内在稳定而非外部控制。'],['黑白双柱','黑柱 B 与白柱 J 对应所罗门圣殿的波阿斯与雅斤，象征对立力量与进入神秘知识的门槛。'],['石榴帷幕','石榴象征生命、女性与繁衍；帷幕表示真相存在，但不会被一次性完全揭开。'],['卷轴 TORA','卷轴既指向律法与传统智慧，也因被衣袍遮住一部分而暗示知识需要逐步理解。'],['脚边新月','月亮象征直觉、周期、梦境与潜意识。'],['蓝色长袍与水面','蓝色与水强调情绪深度、精神宁静与不可见的内在流动。']], colors:'蓝色、白色、黑色构成冷静而神秘的氛围。黑白提示二元世界，蓝色则把注意力引向直觉与潜意识。'},
  'major-3': {overview:'一位头戴十二星冠冕的金发女性，姿态慵懒而充满母性地坐在柔软华丽的长椅上。她身处森林、流水与成熟麦田之间，整幅画不是权力的宫殿，而是生命自然生长的领地。', symbols:[['人物与姿态','女皇身体自然靠坐，神情温和、没有戒备。她的权威不是命令，而是滋养、包容与让事物成熟。'],['十二星冠冕','十二颗星对应十二星座与一年十二个月，象征她与完整自然周期、宇宙秩序相连。'],['权杖','她右手举着顶端为圆球的权杖。圆球象征完整世界，也表示她对现实物质与创生力量的掌管。'],['金星盾牌','红色心形盾牌刻有金星符号。金星对应爱、美、和谐、享受与丰饶；盾牌说明温柔本身也是一种保护力量。'],['石榴长袍','白袍上的红色石榴象征子宫、繁衍与母性本能，也与珀耳塞福涅神话中的生命循环有关。'],['森林与瀑布','茂密森林代表旺盛生命力，流动的水象征情感、滋养与自然持续循环。'],['成熟麦田','金黄色麦田已经成熟，不是刚萌芽，说明女皇对应的是经过照料后能够被看见、被享用的丰收。']], colors:'白色象征纯净与开放，红色石榴代表生命与欲望，绿色森林代表成长，金黄色麦田代表成熟成果。综合色彩营造温暖、丰饶和安全感。'},
  'major-4': {overview:'皇帝端坐在坚硬石座上，身后是荒凉山脉。他穿着盔甲、手持权杖与宝球，画面强调秩序、边界、责任以及建立可持续结构的能力。', symbols:[['人物与坐姿','身体正直、正面凝视，表达明确权威与不容含糊的立场。'],['石制王座','坚硬石座象征制度、规则与长期稳定，也暗示过度僵化的风险。'],['公羊头','对应白羊座，代表主动、领导、勇气与开创性。'],['盔甲','即使坐在王座上仍穿盔甲，说明皇帝时刻准备承担责任与防御风险。'],['安卡权杖与宝球','安卡象征生命与统治，宝球代表现实世界与掌控范围。'],['荒山与细小河流','山脉代表严峻环境与意志，细小水流提示情感并未消失，只是被理性秩序压低。']], colors:'红色强调火元素、意志与行动；灰色石座和山脉强化理性、坚固与克制；盔甲冷色则带出防御性。'},
  'major-5': {overview:'教皇坐在宗教建筑中，面前有两位信徒，脚下交叉双钥匙。他代表传统体系、共同信仰、知识传承与通过既有路径获得指导。', symbols:[['三重冠','三层冠冕可对应精神、思想与物质三个层次的权威。'],['祝福手势','右手做宗教祝福手势，表示传授、认可与连接神圣秩序。'],['双钥匙','交叉钥匙象征进入显性与隐性知识领域的权限。'],['两位信徒','代表师徒关系、共同规范与群体中的学习。'],['红白花纹','一位衣服有玫瑰、一位有百合，重复欲望与纯净、行动与精神的双重主题。']], colors:'红色强调制度权威与仪式感，白色体现精神纯净，灰色建筑让画面显得稳定、正式且不强调个人情绪。'},
  'major-6': {overview:'赤裸的一男一女站在天使之下，背景分别有知识之树与生命之树。恋人牌不仅谈感情，更讲价值选择、坦诚以及选择之后愿意承担的责任。', symbols:[['赤裸人物','没有衣物遮挡，象征关系中的真实、脆弱与坦诚。'],['拉斐尔天使','天使位于高处，代表疗愈、更高价值与超越个人欲望的见证。'],['知识之树与蛇','象征意识、选择、诱惑与获得知识的代价。'],['生命之树与十二火焰','十二团火焰对应十二星座，表示生命力与宇宙秩序。'],['高山','关系与选择背后仍有需要共同面对的成长课题。'],['人物视线','男人看女人，女人看天使，形成从欲望到情感再到更高价值的上升路径。']], colors:'蓝天带来清晰与开放，绿色象征生命成长，红色火焰代表欲望与行动，人物裸色强调真实。'},
  'major-7': {overview:'战士站在战车中，前方黑白两只狮身人面像朝向略有差异。战车牌讲的不是蛮力冲刺，而是把冲突力量整合成同一个方向。', symbols:[['战士与盔甲','战士表情坚定，盔甲表示保护和执行任务的准备。'],['黑白狮身人面像','代表对立欲望、不同方向或内在矛盾，需要意志协调。'],['没有缰绳','战士并非靠物理缰绳控制，而是靠意识、方向与内在掌控。'],['星冠与星幕','星星象征精神目标，战车顶部星幕像随身携带的宇宙秩序。'],['城市与河流','他离开熟悉城市，跨越情感边界，进入主动推进阶段。']], colors:'蓝色强调意志与理性，黑白形成对立，金色星象增加目标感与胜利意味。'},
  'major-8': {overview:'一位身穿白衣的女性温柔地抚摸狮子，头顶悬浮无限符号。力量牌强调以耐心、同理心和稳定自信驯服本能，而不是靠暴力压制。', symbols:[['女性与狮子','柔和的人类意识与强烈动物本能相遇，说明真正掌控来自关系而非对抗。'],['手部动作','她一手轻抚头部、一手靠近下颌，动作温柔却非常稳定。'],['无限符号','代表持续的精神力量、自信与生命能量。'],['白色长袍','象征动机纯净、内在清明。'],['花环腰带','花朵将人物与自然生命力连接，表示力量也包含柔软与美。']], colors:'白色代表纯净和自制，红色花朵代表生命欲望，黄色背景营造信心与清晰。'},
  'major-9': {overview:'隐者独自站在雪山之巅，手持只照亮近处的灯笼。画面强调主动退离喧嚣、通过经验沉淀寻找内在方向。', symbols:[['老人形象','象征经验、成熟与经过时间验证的智慧。'],['灯笼与六芒星','灯光只照亮下一小段路，六芒星代表整合后的智慧与精神指引。'],['长杖','提供现实支撑，也象征长期经验积累。'],['高山与雪地','代表孤独、难度与远离日常喧嚣后获得的高度。'],['低垂视线','注意力向内，不追求外界认可。']], colors:'灰色斗篷与白雪营造安静、克制和抽离感；灯笼中的黄色成为唯一温暖焦点，象征内在光。'},
  'major-10': {overview:'巨大的轮盘位于天空中央，周围有上升与下降的生物，四角坐着阅读书卷的神圣生物。它展示命运周期、处境变化与变化中的稳定法则。', symbols:[['轮盘','象征不断旋转的周期，没有任何位置会永久固定。'],['字母与符号','轮上 TARO、TORA 等字母和炼金符号把命运与法则、转化联系起来。'],['蛇、阿努比斯与狮身人面像','下降、上升与暂时稳定，代表不同阶段中的命运位置。'],['四角生物','对应四福音象征、四固定星座与四元素，表示变化中仍有稳定知识。'],['云层','命运运作发生在超出个人完全控制的层面。']], colors:'蓝色天空代表更宏观秩序，金色轮盘突出重要转折，红黄生物制造变化与运动感。'},
  'major-11': {overview:'正义端坐于两根柱子之间，一手持天平、一手直举宝剑。她代表事实、责任、因果以及做出清晰判断后承担结果。', symbols:[['人物与正面坐姿','姿态稳定、目光直接，象征客观、不回避事实。'],['天平','衡量信息、动机与后果，提醒判断需要充分证据。'],['直立宝剑','代表清晰决定、理性切割与执行结果。'],['双柱与帷幕','类似女祭司的结构，但正义更公开、理性，强调可见规则。'],['方形扣饰','方形象征现实秩序，内部圆形代表完整真理。']], colors:'红袍表现行动与责任，绿色披风象征平衡和稳定，灰色柱子带来制度感。'},
  'major-12': {overview:'倒吊人单脚被绑，身体倒悬，却神情平静，头部出现光环。他不是遭受惩罚，而是主动暂停，从颠倒视角获得领悟。', symbols:[['倒悬姿态','世界被颠倒观看，象征暂停惯性思维与换角度。'],['T形树架','像生命之树，也像十字架，表示牺牲与精神转化。'],['头部光环','停止挣扎后出现领悟与内在清明。'],['腿部姿势','一条腿被绑、另一条弯曲形成十字，限制中仍保留内在选择。'],['平静表情','说明这不是外力惩罚，而是有意识的等待与接受。']], colors:'蓝衣代表精神与直觉，红裤代表仍存在的生命力，黄色光环突出领悟。'},
  'major-13': {overview:'骷髅骑士骑着白马前进，国王倒下，人物以不同姿态面对他，远方双塔之间太阳升起。死神牌描绘不可逆的结束与随之而来的转化。', symbols:[['骷髅骑士','死亡剥离身份与外表，象征变化对所有人一视同仁。'],['白马','白色表示净化，马的前进说明转化不会因抗拒而停止。'],['黑旗与白玫瑰','黑色代表结束，白玫瑰代表净化、生命核心与重生。'],['倒下的国王与众人','权力、年龄和身份都不能阻止周期变化。'],['河流、船与日出','灵魂旅程、过渡与结束之后的新周期。']], colors:'黑白形成结束与净化的强烈对比，远方黄色日光提醒新阶段仍会到来。'},
  'major-14': {overview:'天使一脚踩水、一脚踏地，把水在两只圣杯之间来回倾倒。节制牌展示持续调节、融合差异与让疗愈在过程中发生。', symbols:[['天使','超越个人情绪的协调力量，胸前方形与三角形象征精神进入物质。'],['两只圣杯与流水','不同能量并非一次性混合，而是持续交换、测试与调整。'],['一脚水中一脚地上','潜意识与现实、情绪与行动之间保持平衡。'],['鸢尾花','象征希望、纯净与沟通。'],['远方道路与日冠','平衡不是终点，而是一条通向更完整自我的路径。']], colors:'白衣象征净化，红翼带来行动能量，蓝水与绿色土地营造疗愈、自然和稳定。'},
  'major-15': {overview:'恶魔高坐，男女被锁链束缚，但锁链其实很松。画面直面欲望、依赖、羞耻与自我限制，也暗示人仍拥有觉察和离开的可能。', symbols:[['恶魔形象','结合人、兽与鸟的特征，表示本能、欲望与阴影混合。'],['倒五芒星','物质和欲望压过精神方向。'],['松动锁链','束缚真实存在，但并非完全无法解除；习惯与恐惧常让人不愿离开。'],['男女的角与尾巴','他们逐渐呈现恶魔特征，说明长期依赖会内化成身份。'],['火炬朝下','能量被导向低层欲望、消耗或破坏。']], colors:'黑色背景强化无意识与阴影，红橙火焰代表强烈欲望和消耗，裸色人物强调本能。'},
  'major-16': {overview:'闪电击中高塔，王冠被掀落，人物从高处坠下，塔顶冒出火焰。高塔展示建立在错误基础上的结构被真相突然击破。', symbols:[['闪电','突如其来的事实、觉醒或外部冲击，照亮原先看不见的问题。'],['坠落王冠','自以为稳固的权威、信念或控制被推翻。'],['高塔','封闭而孤立的结构，通常建立在过度自信或错误基础上。'],['坠落人物','旧身份和旧位置无法维持，必须面对失控。'],['二十二团火焰','常与希伯来字母或生命之树路径联系，象征破坏中也包含更高秩序。']], colors:'黑夜代表未知，黄色闪电带来强烈真相，红色火焰表示结构内部已经积累能量。'},
  'major-17': {overview:'裸体女性跪在水边，一脚在水中、一脚在陆地，将两壶水分别倒入池中与土地。天空有一颗大星和七颗小星，画面安静、开放且充满恢复感。', symbols:[['裸体人物','卸下防御、真实面对自己，也表示疗愈需要诚实。'],['一脚水中一脚地上','直觉与现实、潜意识与日常行动之间保持连接。'],['两只水罐','一壶回到水中、一壶滋养土地，象征内外能量重新循环。'],['八颗星','主星提供方向，七颗小星可联系七脉轮或完整精神秩序。'],['树与鸟','远处的鸟常被视为朱鹭，与智慧、沟通和心灵视角有关。']], colors:'蓝色水域带来宁静与疗愈，黄色星光象征希望，绿色土地表示恢复正在现实中扎根。'},
  'major-18': {overview:'月光下，一条小路从水边穿过狗与狼，再延伸到两座塔之间。龙虾从水中爬出，画面像梦境，强调潜意识、模糊与本能反应。', symbols:[['月亮与人脸','月亮同时呈现圆满和弯月形态，暗示事实、感受与想象彼此叠加。'],['狗与狼','狗象征驯化本能，狼象征原始本能，两者都对未知发出反应。'],['龙虾','从深水中出现，代表潜意识中原始、难以命名的感受。'],['两座塔','已知世界边界和进入未知领域的门槛。'],['蜿蜒小路','前路存在，却无法一次看清，只能凭直觉逐步前进。'],['露滴般光芒','月光落下的点状光芒象征潜意识影响和细微信号。']], colors:'深蓝与灰色制造梦境、不确定和情绪氛围；黄色月光虽提供照明，却不像太阳那样清晰。'},
  'major-19': {overview:'赤裸孩子骑在白马上，手持红旗，背后是四朵向日葵与高墙，巨大太阳直接照耀。太阳牌表达清晰、生命力、真实与不再隐藏。', symbols:[['赤裸孩子','代表真实、自由、信任与重新开始。'],['白马','纯净生命力，且没有缰绳，表示行动自然顺畅。'],['红旗','热情、胜利、行动与公开表达。'],['四朵向日葵','对应四元素或四个世界，所有生命朝向光成长。'],['高墙','过去限制仍在身后，但孩子已经越过。'],['太阳光线','直线与波浪线交替，可对应理性与生命能量共同照耀。']], colors:'黄色主导清晰、喜悦与自信；红色强化行动和生命力；白色保持纯净。'},
  'major-20': {overview:'天使在云端吹响号角，棺木中的人们起身回应，远处是无法绕开的山脉。审判讲的是觉醒、复盘与回应内在召唤。', symbols:[['天使号角','无法忽略的消息、召唤与意识觉醒。'],['白底红十字旗','净化、救赎与新的生命阶段。'],['起身的人群','旧身份结束，个体准备以新的理解重新生活。'],['灰色身体','暂时卸下社会身份与个人装饰，回到更本质的自我。'],['远方山脉','最终决定前必须面对的现实与无法逃避的课题。'],['棺木与水面','旧阶段被封存，同时水象征情绪和潜意识中的重生。']], colors:'灰色人物表现过去状态，蓝色水域象征重生，红白旗帜让召唤显得清晰而有行动力。'},
  'major-21': {overview:'舞者位于椭圆花环中央，手持双杖，四角有天使、鹰、狮与牛。世界牌表示四元素、经验与身份被整合，一个周期完整闭合。', symbols:[['中央舞者','姿态自由却平衡，象征经历整合后的自在与完整。'],['椭圆花环','像世界之卵、子宫或数字零，代表完成、保护与新周期入口。'],['两根魔杖','对称双杖表示主动与被动、开始与结束已经协调。'],['紫色飘带','紫色常对应精神成熟，飘带形成无限循环感。'],['四角生物','对应四固定星座、四元素与完整世界结构。'],['双腿交叉','与倒吊人姿态形成呼应，但此处是自由舞蹈而非暂停。']], colors:'绿色花环代表生命完成，紫色象征精神成熟，蓝色背景带来广阔与超越感。'}
};
Object.entries(majorDeepDetails).forEach(([id,x])=>{ tarotDetails[id]={...(tarotDetails[id]||{}),...x, symbols:x.symbols}; });

const wandsDeepDetails = {
  "wands-1": {"summary": "灵感已经点燃，真正重要的是给它一个可以开始的出口。", "element": "火元素", "astrology": "火元素的纯粹种子", "numerology": "1：起点、意志与创造冲动", "overview": "一只手从云中伸出，握着一根正在萌芽的权杖。远处有城堡、山丘与河流，整幅画像一个刚刚被递到你手中的机会：它还没有成为成果，却已经拥有明确的生命力。", "symbols": [["云中之手", "像来自外部或内在深处的召唤，表示机会突然出现，也提醒你需要主动接住。"], ["萌芽权杖", "木杖仍在生长，象征灵感不是完成品，而是一颗需要行动滋养的种子。"], ["飘落叶片", "能量正在扩散，说明创意有感染力，但若不落实也会很快散去。"], ["远方城堡", "代表灵感最终可以落地成现实目标、事业或作品。"], ["山丘与河流", "道路并非完全平坦，情绪与现实条件仍需被跨越。"]], "colors": "明亮天空与绿色嫩芽强调新鲜、开放和生命力；棕色木杖让灵感与现实行动保持联系。", "uprightLong": "正位权杖王牌表示新的计划、创意、热情或事业机会正在萌芽。现在不必把全部路线想清楚，先开始一个最小行动，会比继续等待更有价值。", "reversedLong": "逆位可能表示灵感很多却难以启动，或热情被现实阻力压住。也可能是过度兴奋、准备不足，需要先整理优先级。", "advice": "把今天最想做的想法写成一个十分钟内可以开始的动作。"},
  "wands-2": {"summary": "你已经站上更高的位置，下一步需要在安全与扩张之间作选择。", "element": "火元素", "astrology": "火星在白羊座", "numerology": "2：选择、对照与方向", "overview": "一位身穿红袍的人站在城墙上，一手握权杖，一手托着世界球，望向远方海陆。另一根权杖固定在墙上，画面强调已经拥有基础之后，对更大可能性的规划。", "symbols": [["世界球", "象征视野扩大、国际性与“我还能走多远”的想象。"], ["两根权杖", "一根在手、一根固定，代表冒险与安全、行动与保留之间的选择。"], ["高处城墙", "站得更高所以看得更远，但也与真实道路保持距离。"], ["远方海陆", "未知市场、旅行、新领域或未来版图。"], ["红色长袍", "意志与野心已经形成，不再只是权杖王牌的短暂灵感。"]], "colors": "红色强化企图心，蓝色海洋带来未知与扩张，灰色城墙代表已有安全结构。", "uprightLong": "正位权杖二适合规划、比较选项和扩大视野。你已经不是从零开始，而是在决定如何使用现有资源走向更远处。", "reversedLong": "逆位常见于害怕离开舒适区、计划过多却不行动，或对外部环境评估不足。", "advice": "列出两个方向，并为更想尝试的那个安排一个真实期限。"},
  "wands-3": {"summary": "你的行动已经发出，现在要观察回应，并为下一阶段预留空间。", "element": "火元素", "astrology": "太阳在白羊座", "numerology": "3：扩展、合作与初步成果", "overview": "人物背对观者站在高地，望着海面上的船只，三根权杖立在身旁。画面显示计划已经离开起点，正在等待远方回报与进一步扩张。", "symbols": [["远航船只", "象征项目、消息或资源已经出发，结果尚在途中。"], ["高地视角", "人物能看见更远范围，代表战略视野与对未来的判断。"], ["三根权杖", "从个人灵感进入合作、网络与更大规模。"], ["背向观者", "注意力完全放在未来，而非反复检视过去。"], ["海面", "情势仍在流动，需要耐心等待正确时机。"]], "colors": "橙红色披风带出行动热度，蓝海象征距离和流动，绿色高地表示已有基础。", "uprightLong": "正位表示扩张、合作、等待回报与准备下一阶段。适合联系资源、发布作品、开拓新渠道。", "reversedLong": "逆位可能是计划延迟、合作受阻、视野过窄，或已经出发却缺少后续跟进。", "advice": "检查一件已经开始的事，并主动补上下一步联系或跟进。"},
  "wands-4": {"summary": "值得庆祝的稳定，会让关系与成果真正有落脚之处。", "element": "火元素", "astrology": "金星在白羊座", "numerology": "4：稳定、边界与可持续结构", "overview": "四根权杖搭成花环门架，远处人群举花庆祝，背景是安稳城堡。画面明亮开放，象征阶段成果、归属感、庆典与稳定支持。", "symbols": [["花环门架", "临时的仪式之门，代表一个阶段正式被确认。"], ["四根权杖", "火元素获得四的结构，热情终于有了稳定支撑。"], ["庆祝人群", "成果被共同见证，也表示社群、家人与伙伴的支持。"], ["城堡", "安全基地、家庭、团队或可以长期依靠的空间。"], ["黄色天空", "清晰、喜悦与公开庆祝，没有隐藏冲突。"]], "colors": "黄色和绿色营造温暖丰盛，红色花朵强化喜悦，灰色城堡提供安全感。", "uprightLong": "正位常指庆祝、团聚、稳定关系、搬家、婚礼或阶段成果。它提醒你停下来承认已经完成的部分。", "reversedLong": "逆位可能表示庆祝延迟、家庭或团队气氛不稳，或表面热闹但缺少真正归属。", "advice": "为最近完成的一件事安排一个小小的庆祝或确认仪式。"},
  "wands-5": {"summary": "混乱并不一定是敌意，它也可能是不同力量正在寻找位置。", "element": "火元素", "astrology": "土星在狮子座", "numerology": "5：变化、碰撞与挑战", "overview": "五名年轻人各举权杖，动作交错，看起来像争斗，也像混乱练习。没有明显受伤者，说明这更像竞争、意见冲突与能量失序。", "symbols": [["交错权杖", "观点、目标与行动彼此阻挡，缺少共同规则。"], ["五名人物", "多人参与使局面复杂，没人能单独控制全局。"], ["不同服饰", "背景与立场不同，因此同一问题会被用不同方式理解。"], ["缺少领袖", "没有明确中心，表示协调机制尚未建立。"], ["练习感", "画面不像真正战争，冲突也可能促进成长与能力检验。"]], "colors": "多种鲜艳颜色制造嘈杂与分散感，黄色地面说明冲突仍在可见、可处理的范围内。", "uprightLong": "正位表示竞争、争论、头脑风暴或多人协作中的摩擦。冲突不一定坏，但需要规则与共同目标。", "reversedLong": "逆位可能是回避必要冲突、暗中较劲，或争论逐渐缓和。", "advice": "先确认大家到底在争什么，再决定需要竞争还是合作。"},
  "wands-6": {"summary": "被看见的成功很重要，但真正的价值不能只依赖掌声。", "element": "火元素", "astrology": "木星在狮子座", "numerology": "6：调整、认可与阶段胜利", "overview": "一位骑白马的人头戴胜利花环，权杖上也挂着花环，人群在旁跟随。画面展示公开认可、信心与阶段性成功。", "symbols": [["胜利花环", "古典胜利与荣誉，代表成果获得公开确认。"], ["白马", "行动被赋予正当性与高昂士气。"], ["高举权杖", "目标、旗帜或领导方向被人群看见。"], ["跟随人群", "支持与认可，也提示成功与公众评价之间的关系。"], ["红色披风", "自信、行动力和愿意承担焦点位置。"]], "colors": "红色与绿色形成活力和成长，白马突出光明胜利，黄色背景让认可公开可见。", "uprightLong": "正位表示胜利、认可、好消息、曝光与自信提升。适合展示成果或接受应得肯定。", "reversedLong": "逆位可能是认可延迟、过度依赖外界评价、虚荣或自信不足。", "advice": "接受一次肯定，同时提醒自己成果真正改善了什么。"},
  "wands-7": {"summary": "守住位置需要勇气，也需要判断哪些战斗真的值得。", "element": "火元素", "astrology": "火星在狮子座", "numerology": "7：评估、坚持与防守", "overview": "人物站在高处，手持权杖抵挡下方六根权杖。他拥有地势优势，却也面临多方向压力，象征捍卫立场、竞争与边界。", "symbols": [["高地", "代表已有优势、成果或立场，但也意味着成为目标。"], ["六根来杖", "外部质疑、竞争、请求或同时出现的多项压力。"], ["防守姿态", "人物主动回应而非逃跑，强调勇气和边界。"], ["不同鞋子", "常被解读为仓促上阵或情况尚未完全准备好。"], ["孤身人物", "有些立场必须自己承担，无法依赖所有人理解。"]], "colors": "绿色衣服表示成长成果，橙色地面强调紧张行动，蓝色背景保留理性空间。", "uprightLong": "正位表示坚持立场、面对竞争、保护成果或设定边界。你有优势，但需要集中力量。", "reversedLong": "逆位可能是疲于防守、被压力淹没、边界松动，或把所有意见都当成攻击。", "advice": "只守住最重要的一条边界，不必回应所有声音。"},
  "wands-8": {"summary": "当方向已经确定，速度会自然加快，信息与行动同时抵达。", "element": "火元素", "astrology": "水星在射手座", "numerology": "8：力量流动、效率与推进", "overview": "八根权杖在空中平行飞行，画面没有人物阻挡，远方河流与房屋平静。它是少数完全以运动本身为主题的牌，象征快速进展、消息与旅行。", "symbols": [["飞行权杖", "行动已离手，事件正在快速发展。"], ["平行方向", "多项力量朝同一目标前进，减少了内耗。"], ["无人物画面", "重点不在谁控制，而在事情本身已经启动。"], ["河流", "情势顺畅流动，情绪与现实节奏相互配合。"], ["远方房屋", "速度最终指向一个具体目的地，而非无意义忙碌。"]], "colors": "明亮天空带来清晰，绿色大地代表现实成果，棕色权杖强化直接行动。", "uprightLong": "正位表示快速推进、消息到达、旅行、沟通顺畅或多个环节同时加速。", "reversedLong": "逆位可能是延误、消息混乱、节奏过快或同时处理太多事情。", "advice": "趁方向清晰时完成关键沟通，但不要为了快而省略确认。"},
  "wands-9": {"summary": "你已经走得很远，谨慎是经验，但不必让防备变成封闭。", "element": "火元素", "astrology": "月亮在射手座", "numerology": "9：接近完成、韧性与独立", "overview": "受伤的人紧握权杖，身后八根权杖形成防线。他看向侧方，像在警戒下一次挑战，表现疲惫、经验与最后阶段的坚持。", "symbols": [["头部绷带", "过去冲突留下的伤痕与经验。"], ["紧握权杖", "仍保有行动能力和自我保护意志。"], ["八根防线", "既是积累的成果，也是心理防御。"], ["侧向目光", "持续警戒，可能准确，也可能因旧伤而过度敏感。"], ["站立姿态", "虽然疲惫，却没有倒下，显示韧性和准备完成。"]], "colors": "黄色背景让风险可被看见，绿色衣服象征恢复，棕色权杖构成稳固防线。", "uprightLong": "正位表示韧性、最后坚持、谨慎与保护边界。已经接近完成，不宜轻易放弃。", "reversedLong": "逆位可能是精疲力尽、过度防备、旧伤影响判断，或确实需要暂停。", "advice": "确认你是在保护自己，还是在重复过去的紧张反应。"},
  "wands-10": {"summary": "能力越强越容易承担过多，完成不等于必须独自扛下全部。", "element": "火元素", "astrology": "土星在射手座", "numerology": "10：阶段完成、责任与负荷", "overview": "人物抱着十根沉重权杖走向城镇，视线被遮挡，身体前倾。目标已经很近，但负担让他几乎看不清道路。", "symbols": [["十根权杖", "积累的任务、责任与成果全部集中在一起。"], ["被遮挡视线", "负担过重会让人失去方向和全局判断。"], ["弯曲身体", "意志仍在坚持，但身体已经承担明显压力。"], ["远方城镇", "终点不远，说明责任有完成可能，也提醒需要更聪明地抵达。"], ["独自搬运", "可能不愿授权、求助或重新分配工作。"]], "colors": "棕色权杖占据画面，制造压迫感；绿色田野和城镇暗示成果真实存在。", "uprightLong": "正位表示责任繁重、工作过载、接近完成但压力很大。需要分配、简化和设限。", "reversedLong": "逆位可能是放下负担、责任失控、逃避承诺，或身体已经无法继续承受。", "advice": "今天删掉、延后或交给别人一件并非必须由你完成的事。"},
  "wands-11": {"summary": "好奇心是火焰的第一位使者，它邀请你先探索再定义自己。", "element": "火元素", "astrology": "火元素中的土", "numerology": "侍从：学习、消息与初生人格", "overview": "年轻人站在沙漠中，仰望手中正在发芽的权杖。远处金字塔与荒地强调环境并不成熟，但他的注意力完全被新可能吸引。", "symbols": [["年轻侍从", "代表初学者、消息、新身份与愿意尝试的态度。"], ["仰望权杖", "对灵感充满敬意和好奇，尚未急于控制它。"], ["权杖嫩芽", "想法有生命力，需要练习与经验继续成长。"], ["沙漠", "资源有限，说明热情必须自己创造条件。"], ["金字塔", "远方目标、古老智慧与尚待探索的世界。"]], "colors": "黄色和橙色营造热情、冒险与年轻感；绿色嫩芽成为成长希望。", "uprightLong": "正位表示新消息、创意学习、勇于尝试、热情的人或新的兴趣方向。", "reversedLong": "逆位可能是三分钟热度、缺乏经验、消息延迟或害怕表现得不成熟。", "advice": "允许自己以初学者身份开始，不必一开始就证明专业。"},
  "wands-12": {"summary": "强烈行动力可以快速打开道路，也需要避免把速度误当成方向。", "element": "火元素", "astrology": "火元素中的风", "numerology": "骑士：行动、追求与快速推进", "overview": "骑士骑着跃起的马，手举权杖向前，头盔与衣服上有火蜥蜴图案。背景是干燥荒地，画面充满速度、冒险和不安定。", "symbols": [["跃起战马", "爆发式行动、旅行与难以安静停留。"], ["高举权杖", "目标感强，但注意力容易被下一个刺激吸引。"], ["火蜥蜴图案", "火元素的适应与再生，也象征热情循环。"], ["沙漠地形", "行动依靠自身燃料，环境不能自动提供支持。"], ["羽饰方向", "视觉上强化前进速度与冲动。"]], "colors": "橙红色主导激情与冒险，黄色背景加强高温和急迫感，蓝色少量出现以维持判断。", "uprightLong": "正位表示快速行动、旅行、追求目标、魅力和冒险精神。适合突破，但要确认承诺。", "reversedLong": "逆位可能是冲动、急躁、反复改变方向、行动过度或突然失去热情。", "advice": "出发前写下你真正要抵达的结果，而不只是想摆脱的现状。"},
  "wands-13": {"summary": "成熟的火焰既温暖又坚定，她知道如何让自己和他人一起发光。", "element": "火元素", "astrology": "火元素中的水", "numerology": "王后：内在掌控、魅力与成熟滋养", "overview": "权杖王后端坐王座，手持向日葵与权杖，脚边有黑猫。王座装饰狮子与向日葵，画面兼具热情、自信、亲和力和神秘直觉。", "symbols": [["向日葵", "朝向光生长，象征乐观、生命力与公开表达。"], ["黑猫", "独立、直觉、神秘和对阴影面的自在接纳。"], ["狮子图案", "对应火元素与狮子座的勇气、自尊和领导魅力。"], ["张开的双腿与正面坐姿", "身体开放、自信，不需要隐藏存在感。"], ["萌芽权杖", "即使成熟，创造力仍持续生长。"]], "colors": "黄色与金色强调温暖、自信和可见度；黑猫提供神秘与内在深度；红色强化行动。", "uprightLong": "正位表示自信、魅力、创造力、独立和温暖领导。适合相信自己的判断并鼓舞他人。", "reversedLong": "逆位可能是嫉妒、外强中干、需要认可、情绪化控制，或自信被压低。", "advice": "用热情支持自己，而不是用比较证明自己。"},
  "wands-14": {"summary": "真正的领导不是燃烧所有人，而是让共同愿景能够持续前进。", "element": "火元素", "astrology": "火元素中的火", "numerology": "国王：外在掌控、愿景与领导", "overview": "权杖国王端坐王座，手持萌芽权杖，王座上有狮子与火蜥蜴，脚边也有一只火蜥蜴。画面表现成熟火元素的愿景、领导和长期行动力。", "symbols": [["萌芽权杖", "权力仍与创造、生长相连，而非只剩控制。"], ["狮子图案", "勇气、尊严、领导和公开承担。"], ["火蜥蜴闭环", "火元素完成循环，象征掌握热情并使其持续。"], ["正面王座", "愿意承担决策和被看见的责任。"], ["沙漠背景", "领导者不能只依赖环境，需要主动创造机会与资源。"]], "colors": "橙红和金色营造成熟、权威与热量；绿色嫩芽提醒领导必须服务于成长。", "uprightLong": "正位表示愿景、领导力、创业精神、果断和长期热情。适合定方向并带领行动。", "reversedLong": "逆位可能是专断、急躁、自负、只讲愿景不顾执行，或不敢承担领导位置。", "advice": "今天把一个模糊愿景说成清楚、可执行的下一步。"},
};
Object.entries(wandsDeepDetails).forEach(([id,x])=>{ tarotDetails[id]={...(tarotDetails[id]||{}),...x}; });

const cupsDeepDetails = {
  "cups-1": {summary:"情感正在打开，一个新的感受、关系或直觉入口已经出现。",element:"水元素",astrology:"水元素的纯粹种子",numerology:"1：开始、接纳与情感源头",overview:"一只手从云中托出圣杯，五道水流倾泻而下，白鸽衔着圣饼落入杯中，水面布满莲花。整张牌表现情感、灵感与精神恩典从内在源头涌出的时刻。",symbols:[["云中之手","像被递来的情感机会，也像内心突然恢复感受能力。"],["满溢圣杯","情感不是勉强制造，而是自然充盈到必须流动。"],["五道水流","常对应五种感官或情绪渠道，表示感受正在进入现实经验。"],["白鸽与圣饼","象征纯净祝福、精神连接与更高层次的情感意义。"],["莲花水面","莲花从水中生长，表示情绪也能成为觉察与疗愈的土壤。"]],colors:"蓝白色主导纯净、直觉与情感流动；金色圣杯强调珍贵与承载力；绿色莲叶说明情感会滋养现实生命。",uprightLong:"正位圣杯王牌表示情感开启、新关系、新灵感、疗愈或更深的直觉连接。它不保证结果已经成熟，但说明心已经重新愿意接收。",reversedLong:"逆位可能是情绪堵塞、害怕表达、空虚、过度敏感，或感情能量只在内心涌动却没有出口。",advice:"允许自己真实感受，并为这份感受找到一个温和出口。"},
  "cups-2": {summary:"真正的连接来自平等交换，而不是一方不断靠近、另一方不断退后。",element:"水元素",astrology:"金星在巨蟹座",numerology:"2：互相映照、关系与选择",overview:"两个人面对面交换圣杯，上方有赫尔墨斯双蛇杖与狮首翼饰。画面强调双方自愿、平等回应与情感契约。",symbols:[["交换圣杯","双方都主动参与，表示互惠、回应与关系建立。"],["对视姿态","彼此看见，而非只投射自己的期待。"],["双蛇杖","象征沟通、疗愈、平衡与不同能量的协调。"],["狮首翼饰","激情与精神提升并存，关系既有吸引力也有成长潜能。"],["远方房屋","亲密连接需要在现实生活中找到安稳落点。"]],colors:"蓝色与白色带来信任和坦诚，红橙色强化吸引与生命力，绿色背景表示关系仍在生长。",uprightLong:"正位常指互相吸引、合作、和解、深度沟通或明确的情感回应。重点不只是浪漫，也包括任何建立在平等基础上的联盟。",reversedLong:"逆位可能是关系失衡、沟通断裂、单方面投入、价值观不合，或需要先修复与自己的关系。",advice:"观察这段关系是否真的存在双向回应，而不只是你的想象。"},
  "cups-3": {summary:"共享喜悦会放大情感能量，但真正的亲密也需要真诚而非只有热闹。",element:"水元素",astrology:"水星在巨蟹座",numerology:"3：分享、创造与社群",overview:"三位女性高举圣杯围成圆圈，脚边有果实与丰收作物。画面像一场庆祝，强调友情、支持、共同成果和情绪共鸣。",symbols:[["三只高举的圣杯","情感被公开分享和共同确认。"],["圆形站位","关系没有唯一中心，象征平等、流动与社群连接。"],["舞动姿态","身体参与庆祝，说明快乐不仅停留在语言。"],["丰收果实","共同努力已经结出可以享受的成果。"],["三位女性","常象征友情、姐妹情谊和互相支持的情感网络。"]],colors:"白、红、金三色营造庆典感；绿色和橙色果实象征现实中的丰收与滋养。",uprightLong:"正位表示庆祝、友情、团体支持、聚会、合作成果与情绪上的轻松。",reversedLong:"逆位可能是社交过度、表面热闹、圈子排斥、八卦，或关系边界模糊。",advice:"和真正让你放松的人分享一件值得开心的小事。"},
  "cups-4": {summary:"当情绪疲惫时，新机会即使出现，也可能暂时无法被看见。",element:"水元素",astrology:"月亮在巨蟹座",numerology:"4：停顿、稳定与情感封闭",overview:"人物坐在树下双臂交叉，面前已有三只圣杯，云中之手递来第四只杯子。他的注意力停留在内在，对眼前机会缺乏回应。",symbols:[["交叉双臂","防御、拒绝或暂时不想参与。"],["低头凝视","沉浸于自己的情绪与比较。"],["三只已有圣杯","并非什么都没有，而是已有事物暂时无法带来满足。"],["云中第四杯","新的可能正在出现，但需要主动抬头才能看见。"],["树下静坐","休息与反思有必要，但停留过久会变成封闭。"]],colors:"灰蓝天空和沉静绿色制造停滞感；鲜明圣杯提示机会仍然存在。",uprightLong:"正位表示倦怠、冷淡、无聊、重新评估或需要独处。它有时是拒绝，有时只是情绪系统需要暂停。",reversedLong:"逆位可能是重新恢复兴趣、开始看见机会，也可能是更加封闭、与外界断连。",advice:"不要强迫自己兴奋，但至少确认你拒绝的是机会本身，还是当前的疲惫。"},
  "cups-5": {summary:"失去值得哀悼，但全部注意力都放在倒下的杯子上，会遮住仍然存在的支持。",element:"水元素",astrology:"火星在天蝎座",numerology:"5：失落、变化与情感转折",overview:"黑袍人物低头看着三只倾倒的圣杯，身后还有两只直立的杯子，远处有桥通往房屋。画面核心是失落与尚未被看见的剩余资源。",symbols:[["黑色斗篷","悲伤、收缩和被失落包围的心理状态。"],["三只倒杯","已经发生的损失、遗憾或无法挽回的部分。"],["两只立杯","仍然存在的关系、资源与可能。"],["桥梁","从悲伤走向恢复需要一个过渡过程。"],["远方房屋","安全与归属并未消失，只是暂时不在视线中心。"]],colors:"黑灰色强化哀伤，红绿液体显示不同情感内容，远方浅色建筑保留希望。",uprightLong:"正位表示失落、失望、遗憾、哀伤和对过去的专注。它允许悲伤存在，同时提醒你并未失去一切。",reversedLong:"逆位可能是逐渐走出悲伤、接受现实，也可能是长期无法释怀、反复回望。",advice:"承认一项真实损失，同时列出仍然支持你的两件事。"},
  "cups-6": {summary:"过去可以带来温柔与根系，但不能成为拒绝成长的避难所。",element:"水元素",astrology:"太阳在天蝎座",numerology:"6：回忆、修复与情感回馈",overview:"一名儿童将装满白花的圣杯递给另一名儿童，周围是安稳的庭院与房屋。画面充满纯真、熟悉感和过去记忆。",symbols:[["儿童","纯真、早期经验与未经复杂化的情感。"],["白花圣杯","善意、礼物和不带强迫的情感表达。"],["六只圣杯","过去经验形成完整情感模式，也可能反复影响当下。"],["庭院与房屋","熟悉、安全和归属记忆。"],["远处守卫","即使怀旧，现实世界仍有边界与责任。"]],colors:"黄色庭院营造温暖旧时光，白花象征纯洁，蓝色与红色衣服带出温柔互动。",uprightLong:"正位表示怀旧、旧友、童年、善意、礼物与情感修复。也可能是过去的人或主题再次出现。",reversedLong:"逆位可能是沉溺过去、理想化旧关系、童年议题未解，或终于愿意离开旧模式。",advice:"珍惜一段温柔回忆，但问问它今天能教你什么，而不是要求它重来。"},
  "cups-7": {summary:"选择很多不等于真正自由，清晰来自分辨欲望、幻想与现实代价。",element:"水元素",astrology:"金星在天蝎座",numerology:"7：评估、投射与内在选择",overview:"黑色人影面对云中的七只圣杯，每只杯子盛放不同诱惑或象征物。画面像梦境，表现选择、幻想、欲望和不确定。",symbols:[["七只圣杯","多种可能、欲望与心理投射。"],["云层","选择尚未落地，存在幻想和信息不清。"],["珠宝与城堡","财富、地位和理想生活的诱惑。"],["蛇与龙","本能、危险、转化和不可控力量。"],["蒙布人影","未知愿望或被神秘感放大的期待。"]],colors:"云中鲜艳图像制造诱惑感，黑色人影表示尚未形成明确自我立场。",uprightLong:"正位表示选择过多、幻想、理想化、创意丰富但缺乏聚焦。需要筛选真实可行性。",reversedLong:"逆位可能是终于看清选择、做出决定，也可能是幻想崩塌或被单一执念困住。",advice:"把每个诱人选项后面的现实代价也写出来。"},
  "cups-8": {summary:"离开并不总是失败，有时是承认某些东西已经无法继续滋养你。",element:"水元素",astrology:"土星在双鱼座",numerology:"8：力量重组、离开与寻找意义",overview:"人物背对八只整齐排列的圣杯，在月光下走向山地。杯子并未倾倒，说明离开的不一定是坏事，而是已经不足以满足内在需要。",symbols:[["八只完整圣杯","现状并非彻底崩坏，离开来自更深层的不满足。"],["缺口排列","看似完整中仍有明显空缺。"],["背身离开","主动抽离、结束和寻找新方向。"],["月亮","情绪复杂，决定带有直觉和不确定。"],["山路与河流","寻找意义需要跨越现实与情感的艰难地形。"]],colors:"深蓝夜色强化内省和未知，红色斗篷保留行动意志，灰色山脉表示道路不轻松。",uprightLong:"正位表示离开、放下、结束不再满足的关系或目标，寻找更有意义的方向。",reversedLong:"逆位可能是害怕离开、反复回头、拖延结束，或仓促离开后又怀疑。",advice:"判断你是在逃避困难，还是在诚实承认这条路已经不再适合。"},
  "cups-9": {summary:"满足值得享受，但真正的丰盛不只是得到想要的，也包括知道什么已经足够。",element:"水元素",astrology:"木星在双鱼座",numerology:"9：完成感、独立满足与愿望实现",overview:"人物双臂抱胸坐在九只圣杯前，神情自信满足。圣杯整齐排列，像展示已经获得的成果与享受。",symbols:[["九只圣杯","积累的满足、愿望成果和情感资源。"],["弧形陈列","像舞台背景，表示成果被看见与展示。"],["双臂抱胸","自信、满足，也可能略带自满和封闭。"],["红色帽子","享受、欲望与感官愉悦。"],["蓝色帷幕","丰富成果背后仍有未完全公开的情绪层面。"]],colors:"黄色背景营造明亮满足，红白衣服表现享受与自信，蓝色布幕增加情感深度。",uprightLong:"正位表示愿望实现、满足、享受、舒适与自我肯定。",reversedLong:"逆位可能是表面满足、过度享乐、期待落空，或得到之后仍觉得空。",advice:"享受已经拥有的，同时确认这份满足是否真的来自你自己。"},
  "cups-10": {summary:"情感圆满来自共同创造的安全感，而不是永远没有冲突。",element:"水元素",astrology:"火星在双鱼座",numerology:"10：情感完成、家庭与共同愿景",overview:"一家人在彩虹下举手庆祝，十只圣杯排列在彩虹中，孩子在旁舞蹈，远方有家园。画面表现关系、归属和共同生活愿景。",symbols:[["彩虹十杯","情感经历形成完整弧线，象征祝福和共同愿景。"],["拥抱伴侣","关系中的合作与共同承担。"],["舞蹈儿童","安全环境中的自由、喜悦和未来延续。"],["远方家园","情感需要落实成真实生活结构。"],["举起双手","公开感谢、接受与庆祝。"]],colors:"彩虹色带来完整与希望，绿色土地代表稳定生活，蓝天强化开放与信任。",uprightLong:"正位表示家庭幸福、情感圆满、归属、长期关系与共同价值。",reversedLong:"逆位可能是家庭张力、价值观不一致、理想化幸福，或关系外表完整但内部失联。",advice:"为你想要的关系氛围做一个具体、可重复的小行动。"},
  "cups-11": {summary:"敏感与想象力是一种天赋，前提是学会分辨直觉与情绪投射。",element:"水元素",astrology:"水元素中的土",numerology:"侍从：消息、学习与情感萌芽",overview:"年轻侍从手持圣杯，杯中探出一条鱼。海面在身后，画面轻盈、奇妙，像情绪和直觉突然用意外方式说话。",symbols:[["杯中之鱼","来自潜意识的消息、意外灵感或情感惊喜。"],["年轻侍从","初学者、柔软感受和愿意表达的心。"],["海浪","情绪持续流动，背景并不完全稳定。"],["蓝色衣装","直觉、想象和情感开放。"],["花纹外衣","丰富内在世界与艺术表达。"]],colors:"蓝色主导敏感和直觉，粉色与黄色增加童真、创意和温柔。",uprightLong:"正位表示情感消息、直觉、创作灵感、道歉、告白或敏感年轻人。",reversedLong:"逆位可能是情绪幼稚、幻想过度、难以表达、消息不可靠或对拒绝过度敏感。",advice:"先记录第一感受，再用现实信息验证它。"},
  "cups-12": {summary:"追随感受需要勇气，但成熟的浪漫必须同时尊重现实与边界。",element:"水元素",astrology:"水元素中的风",numerology:"骑士：追求、邀请与情感行动",overview:"骑士骑白马缓慢前行，手托圣杯，前方有河流与山地。与权杖骑士不同，他的动作克制，像带着邀请、提案或情感信息而来。",symbols:[["托起圣杯","情感被郑重呈现，而不是冲动倾倒。"],["白马","善意、理想和温柔动机。"],["缓慢步伐","行动由感受引导，重视氛围与回应。"],["河流","关系与情绪需要持续流动。"],["有翼头盔","想象、信息和浪漫追求。"]],colors:"白色表现理想和诚意，蓝色象征情感深度，红色鱼纹带来欲望与创造。",uprightLong:"正位表示浪漫邀请、追求、创意提案、温柔行动和遵循内心。",reversedLong:"逆位可能是空头承诺、过度理想化、情绪操控、逃避现实或爱情幻想。",advice:"表达心意时，也明确你实际能够承担什么。"},
  "cups-13": {summary:"成熟的共情不是吸收所有情绪，而是在保持边界时仍愿意理解。",element:"水元素",astrology:"水元素中的水",numerology:"王后：内在情感掌控、直觉与滋养",overview:"圣杯王后独坐海边王座，凝视手中唯一带盖的华丽圣杯。海水围绕她，脚边有贝壳和卵石，画面深沉、安静、富有直觉。",symbols:[["封闭圣杯","内心世界珍贵且复杂，不会轻易向所有人开放。"],["凝视杯子","深度内省、直觉与对情绪细节的专注。"],["海边王座","能够接近情绪，却不被海水完全淹没。"],["贝壳图案","接收、保护、女性直觉和潜意识。"],["石质王座","敏感之下仍需要稳定边界。"]],colors:"蓝白色强化直觉、宁静和情绪深度，金色圣杯提示内在世界的珍贵。",uprightLong:"正位表示共情、直觉、温柔、情绪理解、艺术感和成熟照顾。",reversedLong:"逆位可能是情绪吸收过多、牺牲自己、依赖、敏感失控或用温柔隐藏操控。",advice:"关心别人之前，先确认这份情绪是否真的属于你。"},
  "cups-14": {summary:"真正的情绪掌控不是压抑，而是在波动中仍能做出稳定选择。",element:"水元素",astrology:"水元素中的火",numerology:"国王：外在情绪掌控、包容与稳定领导",overview:"圣杯国王的王座漂浮在汹涌海面，他手持圣杯与权杖，远处有船和跃出水面的鱼。周围情绪起伏明显，但他仍保持稳定。",symbols:[["海上王座","情绪环境不断变化，稳定来自内在而非外部平静。"],["圣杯与权杖","同时掌握感受与行动，理性不否定情绪。"],["跃出水面的鱼","潜意识内容会浮现，但不必因此失控。"],["远方船只","现实责任仍在继续，需要在情绪中导航。"],["平静坐姿","成熟、包容和可依赖的情绪领导。"]],colors:"深蓝海水表现情绪复杂，黄色和红色服装带出成熟意志，灰色王座提供稳定。",uprightLong:"正位表示情绪成熟、包容、外交能力、可靠支持和温和领导。",reversedLong:"逆位可能是情绪压抑、冷漠伪装、操控、酒精或逃避问题，或外表平静内里失衡。",advice:"先命名情绪，再决定行动，不要让情绪替你做全部决定。"}
};
Object.entries(cupsDeepDetails).forEach(([id,x])=>{ tarotDetails[id]={...(tarotDetails[id]||{}),...x}; });



const swordsDeepDetails = {"swords-1":{"summary":"清晰是一把双刃剑：它能切开迷雾，也要求你诚实面对答案。","element":"风元素","astrology":"风元素的纯粹种子","numerology":"1：思想开端与真相显现","overview":"云中之手托起一柄直立宝剑，剑尖穿过金冠与花环，远方山脉陡峭。画面表现思想、判断与真相突然变得锋利清晰。","symbols":[["直立宝剑","专注、判断、语言与切开混乱的力量。"],["金冠","思想取得主导权，也象征胜利与权威。"],["花环","清晰带来的突破与认可。"],["云中之手","新的观念或真相像礼物般突然出现。"],["远山","真相并不总舒适，清醒之后仍需面对现实。"]],"colors":"灰白天空强调理性与冷静，金色皇冠表现思想的价值，绿色花环保留成长可能。","uprightLong":"新想法、真相、决定、沟通突破与理性胜利。","reversedLong":"混乱、误解、言语伤害、判断失准，或真相暂时无法被看见。","advice":"把最复杂的问题写成一句清楚的问题。"},"swords-2":{"summary":"暂时不决定也是一种决定，但长期闭眼会让僵局越来越重。","element":"风元素","astrology":"月亮在天秤座","numerology":"2：对立、平衡与犹豫","overview":"蒙眼女子手持两柄交叉宝剑，背后是海水、礁石与月亮。她保持平衡，却也把自己隔绝在信息之外。","symbols":[["蒙眼","拒绝看见、信息不足或主动隔离情绪。"],["交叉宝剑","两个选择彼此抵消，形成僵局。"],["平静坐姿","依靠控制维持暂时稳定。"],["海水与礁石","情绪仍在背景中，且现实存在隐患。"],["新月","直觉已给出微弱提示，但尚未被接纳。"]],"colors":"灰蓝色制造停滞与冷静，白衣保持中立，黑色眼罩强调防御。","uprightLong":"犹豫、僵局、避免冲突、需要更多信息。","reversedLong":"决定被迫出现、压抑失效、信息过载，或终于愿意面对真相。","advice":"先找出你最害怕承认的那个事实。"},"swords-3":{"summary":"痛苦被命名之后，才有可能真正开始愈合。","element":"风元素","astrology":"土星在天秤座","numerology":"3：思想成形与痛苦显化","overview":"一颗红心被三柄宝剑贯穿，背景是阴云与暴雨。画面没有人物，情绪被直接化成一个无法回避的象征。","symbols":[["红心","真实感受与脆弱核心。"],["三柄宝剑","思想、言语或事实对情感造成穿透。"],["暴雨","悲伤被允许外流，而不是继续压在体内。"],["阴云","视野暂时被痛苦覆盖。"],["空旷背景","痛苦具有普遍性，也让人感到孤独。"]],"colors":"红色心脏与灰色天空形成强烈对比，强调情感创伤无法被理性掩盖。","uprightLong":"心碎、失望、分离、悲伤、痛苦真相。","reversedLong":"逐渐疗愈、释放悲伤，也可能是压抑痛苦或旧伤反复。","advice":"不要急着坚强，先允许自己准确说出哪里受伤。"},"swords-4":{"summary":"真正的休息不是逃避，而是让心智重新恢复秩序。","element":"风元素","astrology":"木星在天秤座","numerology":"4：暂停、恢复与精神空间","overview":"骑士雕像平躺在墓台上，三柄剑悬于墙面，一柄剑在侧。彩绘玻璃带来安静的宗教氛围。","symbols":[["平躺骑士","主动停止行动，让身心进入修复。"],["合十双手","祈祷、内省与重新连接内在。"],["墙上三剑","压力仍存在，但暂时被放置。"],["身侧一剑","仍保留必要的警觉与判断。"],["彩窗","精神支持、希望与恢复意义。"]],"colors":"灰石与柔和黄光营造静默，彩窗色彩暗示休息中仍有生命。","uprightLong":"休息、康复、暂停、静心、暂时撤退。","reversedLong":"无法休息、过度停滞、疲惫反弹，或准备重新行动。","advice":"给自己安排一段不被信息打扰的空白。"},"swords-5":{"summary":"赢得争论却失去关系，并不一定是真正的胜利。","element":"风元素","astrology":"金星在水瓶座","numerology":"5：冲突、破裂与价值考验","overview":"前景人物收拢三柄宝剑，脸上带着得意，远处两人离开，另外两柄剑落在地面。风云翻涌，冲突已经结束但代价仍在。","symbols":[["得意表情","胜利可能带着自负、冷酷或报复。"],["地上宝剑","冲突后的损失与被迫放下。"],["远去人物","关系破裂、羞辱或撤退。"],["混乱天空","思想与情绪仍未真正平息。"],["海岸","冲突留下的情绪余波。"]],"colors":"冷灰天空与锐利金属色突出紧张，人物衣服中的红色强化攻击性。","uprightLong":"冲突、争强、代价高昂的胜利、不公平竞争。","reversedLong":"和解、放下争斗，也可能是怨恨未消或冲突转入暗处。","advice":"问自己：这场胜利值得付出什么代价？"},"swords-6":{"summary":"离开风暴并不代表一切立刻轻松，但方向已经改变。","element":"风元素","astrology":"水星在水瓶座","numerology":"6：过渡、移动与恢复秩序","overview":"船夫撑船载着披斗篷的人与孩子渡水，六柄剑立在船头。前方水面平静，身后波纹仍在。","symbols":[["渡船","从旧处境过渡到新阶段。"],["六柄剑","过去的经验与问题被一同带走。"],["披斗篷人物","疲惫、哀伤与需要保护。"],["平静水面","前方逐渐稳定。"],["波动水面","旧情绪尚未完全消退。"]],"colors":"灰蓝色表现沉静与过渡，棕色船只提供现实承载。","uprightLong":"离开困难、旅行、疗愈过渡、逐渐平静。","reversedLong":"难以离开、反复回头、旅程延误，或旧问题被带入新环境。","advice":"允许过程缓慢，但不要否认你已经在移动。"},"swords-7":{"summary":"策略可以保护自己，但长期躲避会让信任一点点流失。","element":"风元素","astrology":"月亮在水瓶座","numerology":"7：策略、独立与隐秘行动","overview":"人物抱走五柄宝剑，回头看向营地，地上还留有两柄。他的动作轻快而谨慎，像在偷偷完成计划。","symbols":[["抱走五剑","带走资源、信息或优势。"],["回头张望","担心被发现，也说明行动缺乏坦荡。"],["留在地上的两剑","计划并不完整，仍有遗漏。"],["远方营地","群体规则与他人利益。"],["踮脚姿态","灵巧、谨慎，也带着逃避。"]],"colors":"黄色背景增加机敏与警觉，红色鞋帽强化主动性，灰剑代表理性策略。","uprightLong":"策略、隐瞒、独立行动、规避规则、机智。","reversedLong":"秘密暴露、良心不安、重新坦白，或自欺被看穿。","advice":"策略之前，先确认自己是否愿意承担被发现的后果。"},"swords-8":{"summary":"很多限制来自你相信自己没有选择，而不是世界真的没有出口。","element":"风元素","astrology":"木星在双子座","numerology":"8：心理束缚与重新掌控","overview":"蒙眼女子被松散绳索绑住，周围八柄宝剑形成围栏，脚下有湿地，远方城堡仍清晰可见。","symbols":[["蒙眼","看不见选择，也可能是不敢看。"],["松散绳索","限制并非完全无法挣脱。"],["八柄宝剑","反复思想形成自我监牢。"],["湿地","情绪不稳让行动更困难。"],["远方城堡","安全与资源并未消失。"]],"colors":"灰色天空强调无力，红色衣裙显示生命力仍在，黄色远景保留可能。","uprightLong":"受困、焦虑、自我限制、无力感。","reversedLong":"挣脱限制、看见选择，也可能是恐惧加剧或自由后无所适从。","advice":"找出一个你今天其实可以做的小选择。"},"swords-9":{"summary":"夜里的恐惧会把问题放大，白天的事实常比想象更有边界。","element":"风元素","astrology":"火星在双子座","numerology":"9：思想极限与焦虑显化","overview":"人物从床上惊醒，双手掩面，九柄宝剑排列在黑暗墙面。被褥上有玫瑰与星座纹样，暗示痛苦来自复杂内在世界。","symbols":[["掩面人物","焦虑、羞耻与无法停止的内耗。"],["九柄宝剑","思想反复累积到极限。"],["黑暗墙面","夜间恐惧与孤立感。"],["雕刻床沿","痛苦并非无缘无故，背后有旧经验。"],["花纹被褥","现实仍有温柔支撑，只是暂时感觉不到。"]],"colors":"黑色占据主体，红黄被褥提供微弱现实感，强化“恐惧大于事实”的对比。","uprightLong":"焦虑、失眠、内疚、灾难化想象。","reversedLong":"焦虑缓解、求助，也可能是恐惧加深或长期压抑。","advice":"把脑中的最坏想象和真实证据分开写。"},"swords-10":{"summary":"结束有时极其痛苦，但最低点也意味着旧循环已经无法继续。","element":"风元素","astrology":"太阳在双子座","numerology":"10：终结、崩溃与新循环前夜","overview":"人物倒在地面，十柄宝剑贯穿背部，天空黑暗，但远方太阳正在升起，水面也逐渐恢复平静。","symbols":[["十柄宝剑","思想与事件累积到不可再承受。"],["俯卧人物","彻底结束与失去控制。"],["黑色天空","极端痛苦与终局感。"],["升起太阳","新阶段已在远方出现。"],["平静水面","情绪会在结束之后重新恢复。"]],"colors":"黑色表现终结，红黄日出象征恢复，蓝水让情绪重新沉淀。","uprightLong":"结束、背叛、崩溃、触底、无法继续。","reversedLong":"复原、最坏已过，也可能是拒绝结束或旧伤拖延。","advice":"不要再证明自己还能忍，先承认这件事已经结束。"},"swords-11":{"summary":"好奇心让你看得更远，但成熟来自先验证再发言。","element":"风元素","astrology":"风元素中的土","numerology":"侍从：观察、消息与思想萌芽","overview":"年轻侍从双手握剑，身体朝前、视线却转向侧后方。风吹动头发与云层，地面起伏，显示思维高度警觉。","symbols":[["双手握剑","认真对待信息与表达。"],["回头视线","观察环境，也可能过度警惕。"],["强风","消息、思想与变化快速流动。"],["群鸟","交流、传播与群体信息。"],["高地","视野开阔但尚未真正行动。"]],"colors":"蓝白天空强化思考，黄色衣服带来好奇与学习，红靴显示行动冲动。","uprightLong":"好奇、学习、消息、观察、坦率表达。","reversedLong":"流言、冲动发言、监视、信息误判、口舌。","advice":"说出口之前，再核对一次事实来源。"},"swords-12":{"summary":"速度可以带来突破，也可能让你在理解之前就先伤害别人。","element":"风元素","astrology":"风元素中的风","numerology":"骑士：行动、追击与思想速度","overview":"骑士骑马急速冲锋，宝剑高举，树木和云层被风吹斜。整张牌几乎全部朝前，表现强烈推进力。","symbols":[["高举宝剑","明确目标、意志与争辩力量。"],["飞奔白马","理想驱动的极速行动。"],["倾斜树木","环境被行动力量推得失衡。"],["盔甲蝴蝶","思想变化与转化潜能。"],["风暴天空","局势紧张且发展迅速。"]],"colors":"蓝灰天空与银色盔甲强化冷锐，红色披风和缰绳增加冲动。","uprightLong":"迅速行动、直言、野心、突破、争辩。","reversedLong":"鲁莽、言语攻击、方向错误、冲突升级。","advice":"先确认方向，再使用速度。"},"swords-13":{"summary":"清晰的边界并不冷酷，它让诚实与尊重都有位置。","element":"风元素","astrology":"风元素中的水","numerology":"王后：内在判断、独立与清醒边界","overview":"宝剑王后端坐王座，一手举剑，一手向前伸出。天空有云，树木被风吹动，她的神情冷静而开放。","symbols":[["直立宝剑","原则、判断与不回避真相。"],["伸出的左手","邀请沟通，但要求诚实。"],["侧面王座","保持观察与独立立场。"],["蝴蝶雕刻","经历痛苦后的思想转化。"],["高空云层","情绪存在，但不主导判断。"]],"colors":"灰蓝色表现理性，白色云层保留复杂感，红色细节点出生命经验。","uprightLong":"理性、独立、诚实、清晰边界、洞察。","reversedLong":"刻薄、冷漠、偏见、过度防御，或被旧伤主导判断。","advice":"用清楚而不伤人的方式说出边界。"},"swords-14":{"summary":"成熟的理性不是没有感情，而是让原则比情绪波动更稳定。","element":"风元素","astrology":"风元素中的火","numerology":"国王：外在判断、权威与理性领导","overview":"宝剑国王正面端坐，右手举剑，王座上有蝴蝶与新月图案。天空较为平静，显示思想已经从混乱走向制度与原则。","symbols":[["正面举剑","公开、公正与明确决断。"],["石质王座","稳定规则与不可轻易动摇的原则。"],["蝴蝶雕刻","思想成熟来自变化与经验。"],["树木与群鸟","理性仍需观察现实环境。"],["蓝色长袍","冷静、沟通与精神权威。"]],"colors":"蓝灰色建立权威与清晰，紫色象征智慧，黄色细节表现理性成果。","uprightLong":"公正、理性领导、法律、专业判断、权威。","reversedLong":"滥用权力、冷酷、操控、偏见，或只讲逻辑不顾人。","advice":"做决定时，把原则写在情绪前面。"}};
