function tarotImageUrl(card){
  let filename='';
  if(card.group==='大阿卡纳'){
    const english=['Fool','Magician','High_Priestess','Empress','Emperor','Hierophant','Lovers','Chariot','Strength','Hermit','Wheel_of_Fortune','Justice','Hanged_Man','Death','Temperance','Devil','Tower','Star','Moon','Sun','Judgement','World'][card.number];
    filename=`RWS_Tarot_${String(card.number).padStart(2,'0')}_${english}.jpg`;
  }else{
    const prefix={权杖:'Wands',圣杯:'Cups',宝剑:'Swords',星币:'Pents'}[card.group];
    filename=`${prefix}${String(card.number).padStart(2,'0')}.jpg`;
  }
  return `https://commons.wikimedia.org/wiki/Special:Redirect/file/${encodeURIComponent(filename)}`;
}
function tarotArtHtml(card, className='', reversed=false){
  return `<div class="tarot-art-wrap ${className} ${reversed?'is-reversed':''}"><img src="${tarotImageUrl(card)}" alt="${escapeAttr(card.name)}标准韦特塔罗牌面" loading="lazy" decoding="async" referrerpolicy="no-referrer" onload="this.classList.add('is-loaded')" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="tarot-art-fallback"><span>${card.icon}</span><b>${escapeHtml(card.name)}</b></div></div>`;
}

