function uid(){ return crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`; }
function loadState(){
  const base = structuredClone(defaultData), raw = localStorage.getItem(STORAGE_KEY);
  if (!raw) return base;
  try {
    const saved = JSON.parse(raw), merged = { ...base, ...saved };
    merged.todos = { ...base.todos, ...(saved.todos || {}) };
    if (!Array.isArray(merged.todos.edit)) merged.todos.edit = [];
    if (Array.isArray(saved.todos?.parcel) && saved.todos.parcel.length) {
      const existing = new Set(merged.todos.edit.map(x => x.id));
      merged.todos.edit.push(...saved.todos.parcel.filter(x => !existing.has(x.id)));
    }
    delete merged.todos.parcel;
    merged.scheduleTodos = { ...base.scheduleTodos, ...(saved.scheduleTodos || {}) };
    merged.folders = (merged.folders || []).map(f => ({ ...f, notes: (f.notes || []).map(n => ({ pinned:false, tags:[], ...n })) }));
    merged.schedule = (merged.schedule || []).map(x => ({ color:'rose', pinned:false, tags:[], ...x }));
    merged.tarotHistory = saved.tarotHistory || {};
    return merged;
  } catch { return base; }
}
function saveState(){ localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }

function renderNav(){
  const mains = Object.entries(navigation).filter(([,item]) => !item.hiddenFromMain);
  mainNav.style.gridTemplateColumns = `repeat(${mains.length},1fr)`;
  mainNav.innerHTML = mains.map(([id,item]) => `<button class="nav-btn ${id===currentMain?'active':''}" data-main="${id}"><span class="nav-icon">${item.icon}</span><span class="nav-label">${item.label}</span></button>`).join('');
  mainNav.querySelectorAll('[data-main]').forEach(btn => btn.onclick = () => { currentMain=btn.dataset.main; currentSub=navigation[currentMain].children[0].id; currentFolderId=null; currentNoteId=null; render(); });
  const children = navigation[currentMain].children;
  subNav.innerHTML = children.map(item => `<button class="nav-btn ${item.id===currentSub?'active':''}" data-sub="${item.id}"><span class="nav-icon">${item.icon}</span><span class="nav-label">${item.label}</span></button>`).join('');
  subNav.querySelectorAll('[data-sub]').forEach(btn => btn.onclick = () => { currentSub=btn.dataset.sub; currentFolderId=null; currentNoteId=null; render(); });
  const hideSidebar = currentMain === 'home';
  subNav.classList.toggle('hidden-nav', hideSidebar); appShell.classList.toggle('no-sidebar', hideSidebar); appShell.classList.toggle('tarot-cottage', currentMain==='tarot');
}
function render(){
  renderNav(); backupBtn.style.display=currentMain==='home'?'grid':'none'; const main=navigation[currentMain], sub=main.children.find(x=>x.id===currentSub);
  pageTitle.textContent=`${main.label} · ${sub.label}`; quickAddBtn.style.display='block';
  if(currentMain==='home') renderDashboard();
  if(currentMain==='media') renderMedia();
  if(currentMain==='schedule') renderSchedule();
  if(currentMain==='health') renderHealth();
  if(currentMain==='reading') renderReading();
  if(currentMain==='tarot') renderTarot();
}

function renderDashboard(){
  quickAddBtn.style.display='none';
  const now=new Date(), today=formatDate(now), weekKey=getWeekKey(now), monthKey=today.slice(0,7);
  const weekStart=startOfWeek(now), weekEnd=new Date(weekStart); weekEnd.setDate(weekEnd.getDate()+6);
  const todayEvents=state.schedule.filter(x=>x.date===today).sort(sortSchedule);
  const weekTodos=completedLast((state.scheduleTodos.week||[]).filter(x=>x.period===weekKey&&!x.done));
  const monthTodos=completedLast((state.scheduleTodos.month||[]).filter(x=>x.period===monthKey&&!x.done));
  const weekEvents=state.schedule.filter(x=>{const d=new Date(x.date+'T00:00:00');return d>=weekStart&&d<=weekEnd;}).sort(sortSchedule);
  const pinnedMonthEvents=state.schedule.filter(x=>x.pinned&&x.date.startsWith(monthKey)).sort(sortSchedule);
  const mediaCount=['shoot','edit','food'].reduce((n,k)=>n+(state.todos[k]||[]).filter(x=>!x.done).length,0);
  const exercise=state.exercises.filter(x=>x.date===today).reduce((n,x)=>n+Number(x.minutes||0),0);
  const hour=now.getHours(), greeting=hour<12?'早上好':hour<18?'下午好':'晚上好';
  const recentRows=[
    ...weekTodos.slice(0,3).map(x=>({icon:'○',title:x.title,label:'本周 Todo'})),
    ...monthTodos.slice(0,3).map(x=>({icon:'○',title:x.title,label:'本月 Todo'})),
    ...weekEvents.slice(0,5).map(x=>({icon:'◫',title:x.title,label:`${formatShortDate(x.date)}${x.time?' '+x.time:''}`})),
    ...pinnedMonthEvents.slice(0,4).map(x=>({icon:'★',title:x.title,label:`本月重点 · ${formatShortDate(x.date)}`}))
  ];
  appContent.innerHTML=`
    ${tarotDashboardHtml(today,greeting)}
    <div class="dashboard-stats">
      ${dashStat('☀️','今日日程',todayEvents.length,'项','schedule','today')}
      ${dashStat('✓','本周 Todo',weekTodos.length,'项','schedule','week')}
      ${dashStat('🎀','自媒体待办',mediaCount,'项','media','shoot')}
      ${dashStat('👟','今日运动',exercise,'分钟','health','exerciseLog')}
    </div>
    <div class="section-title"><h2>今天的安排</h2><button class="mini-link" data-go="schedule|today">查看全部</button></div>
    <div class="card-list">${todayEvents.length?todayEvents.map(scheduleCardHtml).join(''):emptyHtml('☁️','今天还没有具体日程。')}</div>
    <div class="section-title"><h2>近期安排</h2><span>${recentRows.length} 项</span></div>
    <div class="compact-board">${recentRows.length?recentRows.slice(0,12).map(x=>`<div class="compact-row"><span>${x.icon}</span><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.label)}</small></div>`).join(''):'<p class="soft-empty">近期还没有 Todo 或日程。</p>'}</div>`;
  bindGlobalNavigation(); bindScheduleCards(); const tarotBtn=$('dailyTarotCard'); if(tarotBtn) tarotBtn.onclick=()=>enterTarotCenter('today');
}
function dashStat(icon,label,value,unit,main,sub){return `<button class="dash-stat" data-go="${main}|${sub}"><span>${icon}</span><small>${label}</small><strong>${value}<i>${unit}</i></strong></button>`;}
function bindGlobalNavigation(){ appContent.querySelectorAll('[data-go]').forEach(btn=>btn.onclick=()=>{[currentMain,currentSub]=btn.dataset.go.split('|');currentFolderId=null;render();}); }

function renderMedia(){ if(['shoot','edit','food'].includes(currentSub)) renderTodoList(currentSub); else renderCopywriting(); }
function renderTodoList(type){
  const list=completedLast(state.todos[type]||[]);
  appContent.innerHTML=`<div class="section-title"><h2>全部事项</h2><span>${list.filter(x=>x.done).length}/${list.length} 已完成</span></div><div class="card-list sortable-list" id="mediaTodoList">${list.length?list.map(todo=>todoCardHtml(todo,'media')).join(''):emptyHtml('✓','这里还没有事项，点右上角＋新建。')}</div>`;
  bindTodoActions(type); enablePointerSort($('mediaTodoList'), ids=>{const byId=new Map((state.todos[type]||[]).map(x=>[x.id,x]));state.todos[type]=completedLast(ids.map(id=>byId.get(id)).filter(Boolean));saveState();render();});
}
function todoCardHtml(todo,kind){return `<div class="card ${todo.done?'done':''} sortable-item" data-sort-id="${todo.id}"><div class="card-row"><button class="drag-handle" data-drag-handle aria-label="按住拖拽排序">≡</button><input class="todo-check" type="checkbox" ${todo.done?'checked':''} data-toggle-${kind}-todo="${todo.id}"><div class="grow"><h3>${escapeHtml(todo.title)}</h3>${todo.note?`<p>${escapeHtml(todo.note)}</p>`:''}</div><button class="icon-btn danger" data-delete-${kind}-todo="${todo.id}">×</button></div></div>`;}
function bindTodoActions(type){
  appContent.querySelectorAll('[data-toggle-media-todo]').forEach(el=>el.onchange=()=>{const x=state.todos[type].find(i=>i.id===el.dataset.toggleMediaTodo);if(x)x.done=el.checked;saveState();render();});
  appContent.querySelectorAll('[data-delete-media-todo]').forEach(el=>el.onclick=()=>{state.todos[type]=state.todos[type].filter(x=>x.id!==el.dataset.deleteMediaTodo);saveState();render();});
}
function renderCopywriting(){
  if(currentFolderId && currentNoteId) return renderNoteWorkspace();
  if(currentFolderId) return renderFolderNotes();
  appContent.innerHTML=`<div class="section-title"><h2>文件夹</h2><span>${state.folders.length} 个</span></div><div class="folder-grid">${state.folders.map(f=>`<button class="folder" data-folder="${f.id}"><span class="folder-icon">📁</span><div><h3>${escapeHtml(f.name)}</h3><p>${f.notes.length} 条 · ${f.notes.filter(n=>n.pinned).length} 条置顶</p></div></button>`).join('')}</div>`;
  appContent.querySelectorAll('[data-folder]').forEach(btn=>btn.onclick=()=>{currentFolderId=btn.dataset.folder;render();});
}
function renderFolderNotes(){
  const folder=state.folders.find(f=>f.id===currentFolderId); if(!folder){currentFolderId=null;currentNoteId=null;return render();}
  pageTitle.textContent=`文案 · ${folder.name}`;
  const notes=[...(folder.notes||[])].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||(b.updatedAt||0)-(a.updatedAt||0));
  appContent.innerHTML=`<div class="notes-list-view"><div class="notes-list-toolbar"><button class="text-btn" id="backFoldersBtn">‹ 文件夹</button><button class="notes-new-btn" id="newNoteInlineBtn">✎ 新建备忘录</button></div><div class="notes-folder-heading"><h2>${escapeHtml(folder.name)}</h2><span>${notes.length} 条</span></div><div class="notes-search-shell"><span>⌕</span><input id="folderNoteSearch" placeholder="搜索此文件夹"></div><div class="notes-ios-list sortable-list" id="noteList">${notes.length?notes.map(n=>`<div class="notes-ios-row sortable-item ${n.pinned?'pinned-card':''}" data-sort-id="${n.id}"><button class="drag-handle note-drag" data-drag-handle aria-label="拖动排序">≡</button><button class="note-open" data-note="${n.id}"><div class="note-row-title">${n.pinned?'<span class="pin-mark">★</span>':''}<strong>${escapeHtml(n.title||'新备忘录')}</strong></div><p>${escapeHtml((n.content||'暂无内容').replace(/\n+/g,' '))}</p><small>${formatNoteUpdated(n.updatedAt)}${(n.tags||[]).length?' · '+escapeHtml(n.tags.join('、')):''}</small></button></div>`).join(''):emptyHtml('✎','这个文件夹还没有备忘录。')}</div></div>`;
  $('backFoldersBtn').onclick=()=>{currentFolderId=null;currentNoteId=null;render();};
  $('newNoteInlineBtn').onclick=()=>createAndOpenNote(folder.id);
  appContent.querySelectorAll('[data-note]').forEach(btn=>btn.onclick=()=>{currentNoteId=btn.dataset.note;render();});
  const search=$('folderNoteSearch'); search.oninput=()=>{const q=search.value.trim().toLowerCase();appContent.querySelectorAll('.notes-ios-row').forEach(row=>{const note=folder.notes.find(n=>n.id===row.dataset.sortId);row.hidden=!!q&&!`${note?.title||''} ${note?.content||''} ${(note?.tags||[]).join(' ')}`.toLowerCase().includes(q);});};
  enablePointerSort($('noteList'),ids=>{folder.notes=ids.map(id=>folder.notes.find(x=>x.id===id)).filter(Boolean);saveState();});
}

function createAndOpenNote(folderId){
  const folder=state.folders.find(f=>f.id===folderId); if(!folder)return;
  const note={id:uid(),title:'新备忘录',content:'',tags:[],pinned:false,updatedAt:Date.now()};
  folder.notes.unshift(note); currentFolderId=folderId; currentNoteId=note.id; saveState(); render();
  setTimeout(()=>{const title=$('noteWorkspaceTitle');title?.focus();title?.select();},80);
}
function renderNoteWorkspace(){
  const folder=state.folders.find(f=>f.id===currentFolderId), note=folder?.notes.find(n=>n.id===currentNoteId);
  if(!folder||!note){currentNoteId=null;return renderFolderNotes();}
  pageTitle.textContent='文案 · 备忘录'; quickAddBtn.style.display='none';
  appContent.innerHTML=`<div class="ios-note-workspace"><div class="ios-note-toolbar"><button class="text-btn" id="backNoteListBtn">‹ ${escapeHtml(folder.name)}</button><span id="noteSaveStatus">已保存</span><div class="ios-note-actions"><button id="copyNoteBtn" class="note-tool-btn" title="复制全文">⧉</button><button id="pinNoteBtn" class="note-tool-btn ${note.pinned?'active':''}" title="置顶">★</button><button id="noteMoreBtn" class="note-tool-btn" title="更多">•••</button></div></div><input id="noteWorkspaceTitle" class="ios-note-title" value="${escapeAttr(note.title||'')}" placeholder="标题"><div class="ios-note-meta"><input id="noteWorkspaceTags" value="${escapeAttr((note.tags||[]).join(', '))}" placeholder="添加标签，用逗号分隔"><span>${formatNoteUpdated(note.updatedAt)}</span></div><textarea id="noteWorkspaceContent" class="ios-note-body" placeholder="开始写文案…">${escapeHtml(note.content||'')}</textarea><div id="noteMorePanel" class="note-more-panel hidden"><button id="selectAllNoteBtn">全选正文</button><button id="deleteWorkspaceNoteBtn" class="danger-text">删除备忘录</button></div></div>`;
  $('backNoteListBtn').onclick=()=>{flushNoteWorkspace(note);currentNoteId=null;render();};
  const title=$('noteWorkspaceTitle'), content=$('noteWorkspaceContent'), tags=$('noteWorkspaceTags'), status=$('noteSaveStatus');
  const queue=()=>{status.textContent='正在保存…';clearTimeout(noteSaveTimer);noteSaveTimer=setTimeout(()=>{flushNoteWorkspace(note);status.textContent='已保存';},450);};
  title.oninput=queue; content.oninput=queue; tags.oninput=queue;
  $('pinNoteBtn').onclick=()=>{note.pinned=!note.pinned;$('pinNoteBtn').classList.toggle('active',note.pinned);flushNoteWorkspace(note);};
  $('copyNoteBtn').onclick=async()=>{const text=[title.value.trim(),content.value].filter(Boolean).join('\n\n');try{await navigator.clipboard.writeText(text);status.textContent='已复制全文';setTimeout(()=>status.textContent='已保存',1300);}catch{content.focus();content.select();document.execCommand('copy');status.textContent='已复制全文';}};
  $('noteMoreBtn').onclick=()=>$('noteMorePanel').classList.toggle('hidden');
  $('selectAllNoteBtn').onclick=()=>{content.focus();content.select();$('noteMorePanel').classList.add('hidden');};
  $('deleteWorkspaceNoteBtn').onclick=()=>{if(confirm(`确定删除「${note.title||'这条备忘录'}」吗？`)){folder.notes=folder.notes.filter(n=>n.id!==note.id);saveState();currentNoteId=null;render();}};
}
function flushNoteWorkspace(note){
  const title=$('noteWorkspaceTitle'),content=$('noteWorkspaceContent'),tags=$('noteWorkspaceTags'); if(!title||!content)return;
  note.title=title.value.trim()||'新备忘录'; note.content=content.value; note.tags=parseTags(tags?.value||''); note.updatedAt=Date.now(); updateTags(note.tags); saveState();
}
function formatNoteUpdated(ts){if(!ts)return '刚刚';const d=new Date(ts),today=new Date();if(formatDate(d)===formatDate(today))return `今天 ${pad(d.getHours())}:${pad(d.getMinutes())}`;return `${d.getMonth()+1}月${d.getDate()}日`;}

function renderSchedule(){
  if(currentSub==='month') return renderMonthSchedule();
  if(currentSub==='week') return renderWeekSchedule();
  renderScheduleListView();
}
function renderMonthSchedule(){
  const y=scheduleMonthDate.getFullYear(), m=scheduleMonthDate.getMonth(), monthKey=`${y}-${pad(m+1)}`;
  const todos=completedLast((state.scheduleTodos.month||[]).filter(x=>x.period===monthKey));
  const monthEvents=state.schedule.filter(x=>x.date.startsWith(monthKey)).sort(sortSchedule);
  if(!selectedMonthDate.startsWith(monthKey)) selectedMonthDate=`${monthKey}-01`;
  const days=new Date(y,m+1,0).getDate(), lead=(new Date(y,m,1).getDay()+6)%7, cells=[];
  for(let i=0;i<lead;i++)cells.push('<div class="month-day blank"></div>');
  for(let day=1;day<=days;day++){
    const date=`${monthKey}-${pad(day)}`, ev=monthEvents.filter(x=>x.date===date), selected=date===selectedMonthDate;
    cells.push(`<button class="month-day ${selected?'selected':''} ${date===formatDate(new Date())?'today':''}" data-month-day="${date}"><span class="day-number">${day}</span><div class="event-chips">${ev.slice(0,2).map(x=>`<span style="--event:${colorOf(x).hex};--event-soft:${colorOf(x).soft}">${escapeHtml(x.title)}</span>`).join('')}${ev.length>2?`<small>+${ev.length-2}</small>`:''}</div></button>`);
  }
  const selectedEvents=monthEvents.filter(x=>x.date===selectedMonthDate);
  appContent.innerHTML=`    ${periodTodoSection('month',todos,'本月 Todo')}
    <div class="calendar-toolbar"><button class="calendar-arrow" id="prevScheduleMonth">‹</button><h2>${y} 年 ${m+1} 月</h2><button class="calendar-arrow" id="nextScheduleMonth">›</button></div>
    <div class="weekday-row monday"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span></div>
    <div class="month-calendar">${cells.join('')}</div>
    <div class="section-title"><h2>${formatShortDate(selectedMonthDate)} 的事件</h2><button class="mini-link" id="addSelectedDate">＋ 添加</button></div>
    <div class="card-list">${selectedEvents.length?selectedEvents.map(scheduleCardHtml).join(''):emptyHtml('🌙','这一天还没有事件，点击“添加”。')}</div>`;
  $('prevScheduleMonth').onclick=()=>{scheduleMonthDate=new Date(y,m-1,1);selectedMonthDate=formatDate(scheduleMonthDate);render();};
  $('nextScheduleMonth').onclick=()=>{scheduleMonthDate=new Date(y,m+1,1);selectedMonthDate=formatDate(scheduleMonthDate);render();};
  $('addSelectedDate').onclick=()=>openScheduleModal(null,selectedMonthDate);
  appContent.querySelectorAll('[data-month-day]').forEach(btn=>btn.onclick=()=>{selectedMonthDate=btn.dataset.monthDay;render();});
  bindScheduleTodoActions('month'); bindScheduleCards(); enableTodoSortForPeriod('month',monthKey);
}
function renderWeekSchedule(){
  const start=startOfWeek(scheduleWeekDate), weekKey=formatDate(start), end=new Date(start);end.setDate(end.getDate()+6);
  const todos=completedLast((state.scheduleTodos.week||[]).filter(x=>x.period===weekKey));
  const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d;});
  appContent.innerHTML=`    ${periodTodoSection('week',todos,'本周 Todo')}
    <div class="calendar-toolbar"><button class="calendar-arrow" id="prevScheduleWeek">‹</button><h2>${formatShortDate(formatDate(start))} — ${formatShortDate(formatDate(end))}</h2><button class="calendar-arrow" id="nextScheduleWeek">›</button></div>
    <div class="week-board">${days.map(d=>{const date=formatDate(d),ev=state.schedule.filter(x=>x.date===date).sort(sortSchedule);return `<section class="week-column ${date===formatDate(new Date())?'today-column':''}"><button class="week-heading" data-add-date="${date}"><strong>${['周日','周一','周二','周三','周四','周五','周六'][d.getDay()]}</strong><span>${d.getMonth()+1}/${d.getDate()}</span></button><div>${ev.length?ev.map(x=>`<button class="week-event" style="--event:${colorOf(x).hex};--event-soft:${colorOf(x).soft}" data-edit-schedule="${x.id}"><small>${x.time||'全天'}</small><strong>${escapeHtml(x.title)}</strong></button>`).join(''):'<p class="week-empty">暂无安排</p>'}</div></section>`;}).join('')}</div>`;
  $('prevScheduleWeek').onclick=()=>{scheduleWeekDate=new Date(start);scheduleWeekDate.setDate(start.getDate()-7);render();};
  $('nextScheduleWeek').onclick=()=>{scheduleWeekDate=new Date(start);scheduleWeekDate.setDate(start.getDate()+7);render();};
  appContent.querySelectorAll('[data-add-date]').forEach(btn=>btn.onclick=()=>openScheduleModal(null,btn.dataset.addDate));
  appContent.querySelectorAll('[data-edit-schedule]').forEach(btn=>btn.onclick=()=>openScheduleModal(btn.dataset.editSchedule));
  bindScheduleTodoActions('week'); enableTodoSortForPeriod('week',weekKey);
}
function renderScheduleListView(){
  const now=new Date(), filtered=state.schedule.filter(x=>currentSub==='today'?x.date===formatDate(now):new Date(x.date+'T00:00:00').getFullYear()===now.getFullYear()).sort(sortSchedule);
  appContent.innerHTML=`<div class="section-title"><h2>具体日程</h2><span>${filtered.length} 项</span></div><div class="card-list">${filtered.length?filtered.map(scheduleCardHtml).join(''):emptyHtml('◫','当前视图还没有日程。')}</div>`;
  bindScheduleCards();
}
function periodTodoSection(type,todos,title){todos=completedLast(todos);return `<div class="section-title"><h2>${title}</h2><span>${todos.filter(x=>x.done).length}/${todos.length} 已完成</span></div><div class="card-list sortable-list schedule-todo-list" id="periodTodoList">${todos.length?todos.map(x=>todoCardHtml(x,'schedule')).join(''):emptyHtml('✓',`还没有${title}，点右上角＋添加。`)}</div>`;}
function enableTodoSortForPeriod(type,key){enablePointerSort($('periodTodoList'),ids=>{const all=state.scheduleTodos[type]||[], inPeriod=completedLast(ids.map(id=>all.find(x=>x.id===id)).filter(Boolean)), others=all.filter(x=>x.period!==key);state.scheduleTodos[type]=[...others,...inPeriod];saveState();render();});}
function bindScheduleTodoActions(type){
  appContent.querySelectorAll('[data-toggle-schedule-todo]').forEach(el=>el.onchange=()=>{const x=state.scheduleTodos[type].find(i=>i.id===el.dataset.toggleScheduleTodo);if(x)x.done=el.checked;saveState();render();});
  appContent.querySelectorAll('[data-delete-schedule-todo]').forEach(el=>el.onclick=()=>{state.scheduleTodos[type]=state.scheduleTodos[type].filter(x=>x.id!==el.dataset.deleteScheduleTodo);saveState();render();});
}
function scheduleCardHtml(x){const c=colorOf(x);return `<div class="card schedule-card ${x.pinned?'pinned-card':''}" style="--event:${c.hex};--event-soft:${c.soft}"><div class="card-row"><div class="event-rail"></div><div class="grow"><div class="schedule-time">${x.pinned?'<span class="pin-mark">★ 置顶</span>':''}<span>${formatShortDate(x.date)}</span><strong>${x.time||'全天'}</strong></div><h3>${escapeHtml(x.title)}</h3>${tagHtml(x.tags)}${x.note?`<p>${escapeHtml(x.note)}</p>`:''}</div><button class="icon-btn" data-edit-schedule="${x.id}">✎</button></div></div>`;}
function bindScheduleCards(){appContent.querySelectorAll('[data-edit-schedule]').forEach(btn=>btn.onclick=()=>openScheduleModal(btn.dataset.editSchedule));}
function colorOf(x){return eventColors[x.color]||eventColors.rose;}

function renderHealth(){
  if(currentSub==='exerciseLog'){
    appContent.innerHTML=`<div class="card-list">${state.exercises.length?[...state.exercises].reverse().map(x=>`<div class="card"><div class="card-row"><div class="grow"><h3>${escapeHtml(x.type)}</h3><p>${x.date} · ${x.minutes} 分钟${x.note?'<br>'+escapeHtml(x.note):''}</p></div><button class="icon-btn danger" data-delete-exercise="${x.id}">×</button></div></div>`).join(''):emptyHtml('🏃','还没有运动记录。')}</div>`;
    appContent.querySelectorAll('[data-delete-exercise]').forEach(btn=>btn.onclick=()=>{state.exercises=state.exercises.filter(x=>x.id!==btn.dataset.deleteExercise);saveState();render();});
  }else{
    const total=state.exercises.reduce((n,x)=>n+Number(x.minutes||0),0), month=formatDate(new Date()).slice(0,7), thisMonth=state.exercises.filter(x=>x.date.startsWith(month)).reduce((n,x)=>n+Number(x.minutes||0),0), days=new Set(state.exercises.map(x=>x.date)).size;
    appContent.innerHTML=`<div class="stat-grid"><div class="stat-card"><span>累计运动</span><strong>${total}</strong><span>分钟</span></div><div class="stat-card"><span>本月运动</span><strong>${thisMonth}</strong><span>分钟</span></div><div class="stat-card"><span>运动天数</span><strong>${days}</strong><span>天</span></div><div class="stat-card"><span>平均每次</span><strong>${state.exercises.length?Math.round(total/state.exercises.length):0}</strong><span>分钟</span></div></div>`;quickAddBtn.style.display='none';
  }
}
function renderReading(){
  if(currentSub==='booklist'){
    appContent.innerHTML=`<div class="card-list">${state.books.length?state.books.map(b=>`<div class="card"><div class="card-row"><div class="grow"><h3>${escapeHtml(b.title)}</h3><p>${escapeHtml(b.author||'作者未填写')} · ${b.status}</p><div class="progress"><div style="width:${Number(b.progress)||0}%"></div></div></div><button class="icon-btn danger" data-delete-book="${b.id}">×</button></div></div>`).join(''):emptyHtml('📚','还没有添加书籍。')}</div>`;
    appContent.querySelectorAll('[data-delete-book]').forEach(btn=>btn.onclick=()=>{state.books=state.books.filter(x=>x.id!==btn.dataset.deleteBook);saveState();render();});
  }else{
    const y=readingCalendarDate.getFullYear(),m=readingCalendarDate.getMonth(),prefix=`${y}-${pad(m+1)}`,days=new Date(y,m+1,0).getDate(),lead=new Date(y,m,1).getDay(),cells=[];
    for(let i=0;i<lead;i++)cells.push('<span class="day-cell blank"></span>');for(let d=1;d<=days;d++){const date=`${prefix}-${pad(d)}`;cells.push(`<button class="day-cell ${state.readingDays[date]?'read':''}" data-reading-day="${date}">${d}</button>`);}
    const count=Object.keys(state.readingDays).filter(x=>x.startsWith(prefix)&&state.readingDays[x]).length;
    appContent.innerHTML=`<div class="calendar-toolbar"><button class="calendar-arrow" id="prevReadingMonth">‹</button><h2>${y} 年 ${m+1} 月</h2><button class="calendar-arrow" id="nextReadingMonth">›</button></div><div class="section-title"><h2>本月记录</h2><span>${count} 天</span></div><div class="weekday-row"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span></div><div class="calendar-grid">${cells.join('')}</div>`;
    $('prevReadingMonth').onclick=()=>{readingCalendarDate=new Date(y,m-1,1);render();};$('nextReadingMonth').onclick=()=>{readingCalendarDate=new Date(y,m+1,1);render();};appContent.querySelectorAll('[data-reading-day]').forEach(btn=>btn.onclick=()=>{state.readingDays[btn.dataset.readingDay]=!state.readingDays[btn.dataset.readingDay];saveState();render();});quickAddBtn.style.display='none';
  }
}

function handleQuickAdd(){
  if(currentMain==='media'&&['shoot','edit','food'].includes(currentSub))return openTodoModal(currentSub);
  if(currentMain==='media'&&currentSub==='copy')return currentFolderId?createAndOpenNote(currentFolderId):openFolderModal();
  if(currentMain==='schedule')return ['month','week'].includes(currentSub)?openScheduleChoiceModal():openScheduleModal();
  if(currentMain==='health'&&currentSub==='exerciseLog')return openExerciseModal();
  if(currentMain==='reading'&&currentSub==='booklist')return openBookModal();
}
function openTodoModal(type){openModal('新建事项',`<form id="todoForm"><div class="form-group"><label>事项名称</label><input class="input" name="title" required placeholder="例如：拍摄夏日穿搭视频"></div><div class="form-group"><label>备注（可选）</label><textarea class="textarea" name="note"></textarea></div><button class="primary-btn">保存</button></form>`);$('todoForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.todos[type].push({id:uid(),title:f.get('title').trim(),note:f.get('note').trim(),done:false});saveState();closeModal();render();};}
function openFolderModal(){openModal('新建文件夹',`<form id="folderForm"><div class="form-group"><label>文件夹名称</label><input class="input" name="name" required placeholder="例如：小红书文案"></div><button class="primary-btn">创建文件夹</button></form>`);$('folderForm').onsubmit=e=>{e.preventDefault();state.folders.push({id:uid(),name:new FormData(e.target).get('name').trim(),notes:[]});saveState();closeModal();render();};}
function openNoteEditor(folderId,noteId=null){
  currentFolderId=folderId;
  if(noteId){currentNoteId=noteId;render();}
  else createAndOpenNote(folderId);
}

function openScheduleChoiceModal(){const label=currentSub==='month'?'月 Todo':'周 Todo';openModal('添加安排',`<div class="choice-grid"><button class="choice-card" id="addTodoChoice"><span>✓</span><strong>添加${label}</strong><small>还没有确定具体日期</small></button><button class="choice-card" id="addScheduleChoice"><span>◫</span><strong>添加具体日程</strong><small>已经确定日期或时间</small></button></div>`);$('addTodoChoice').onclick=()=>openScheduleTodoModal(currentSub);$('addScheduleChoice').onclick=()=>openScheduleModal(null,currentSub==='month'?selectedMonthDate:formatDate(scheduleWeekDate));}
function openScheduleTodoModal(type){const period=type==='month'?`${scheduleMonthDate.getFullYear()}-${pad(scheduleMonthDate.getMonth()+1)}`:formatDate(startOfWeek(scheduleWeekDate)),label=type==='month'?'月 Todo':'周 Todo';openModal(`新建${label}`,`<form id="scheduleTodoForm"><div class="form-group"><label>事项名称</label><input class="input" name="title" required></div><div class="form-group"><label>备注（可选）</label><textarea class="textarea" name="note"></textarea></div><button class="primary-btn">保存${label}</button></form>`);$('scheduleTodoForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.scheduleTodos[type].push({id:uid(),title:f.get('title').trim(),note:f.get('note').trim(),done:false,period});saveState();closeModal();render();};}
function openScheduleModal(id=null,defaultDate=null){
  const item=id?state.schedule.find(x=>x.id===id):null;
  openModal(item?'编辑日程':'新建日程',`<form id="scheduleForm"><div class="form-group"><label>日程名称</label><input class="input" name="title" required value="${item?escapeAttr(item.title):''}"></div><div class="form-row"><div class="form-group"><label>日期</label><input class="input" type="date" name="date" required value="${item?.date||defaultDate||formatDate(new Date())}"></div><div class="form-group"><label>时间（可选）</label><input class="input" type="time" name="time" value="${item?.time||''}"></div></div><div class="form-group"><label>标注颜色</label><div class="color-options">${Object.entries(eventColors).map(([k,c])=>`<label><input type="radio" name="color" value="${k}" ${(item?.color||'rose')===k?'checked':''}><span style="--swatch:${c.hex}">${c.name}</span></label>`).join('')}</div></div><div class="form-group"><label>标签（用逗号分隔）</label><input class="input" name="tags" value="${item?escapeAttr((item.tags||[]).join(', ')):''}" placeholder="例如：工作, 会议"></div><label class="switch-row"><input type="checkbox" name="pinned" ${item?.pinned?'checked':''}><span>⭐ 置顶为重要日程</span></label><div class="form-group"><label>备注</label><textarea class="textarea" name="note">${item?escapeHtml(item.note||''):''}</textarea></div><button class="primary-btn">${item?'保存修改':'保存日程'}</button>${item?'<button type="button" id="deleteScheduleBtn" class="secondary-btn">删除这项日程</button>':''}</form>`);
  $('scheduleForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),data={title:f.get('title').trim(),date:f.get('date'),time:f.get('time'),color:f.get('color'),tags:parseTags(f.get('tags')),pinned:f.get('pinned')==='on',note:f.get('note').trim()};if(item)Object.assign(item,data);else state.schedule.push({id:uid(),...data});updateTags(data.tags);selectedMonthDate=data.date;saveState();closeModal();render();};
  if(item)$('deleteScheduleBtn').onclick=()=>{state.schedule=state.schedule.filter(x=>x.id!==item.id);saveState();closeModal();render();};
}
function openExerciseModal(){openModal('记录运动',`<form id="exerciseForm"><div class="form-group"><label>运动类型</label><input class="input" name="type" required></div><div class="form-group"><label>日期</label><input class="input" type="date" name="date" required value="${formatDate(new Date())}"></div><div class="form-group"><label>时长（分钟）</label><input class="input" type="number" name="minutes" min="1" required></div><div class="form-group"><label>备注</label><textarea class="textarea" name="note"></textarea></div><button class="primary-btn">保存记录</button></form>`);$('exerciseForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.exercises.push({id:uid(),type:f.get('type').trim(),date:f.get('date'),minutes:Number(f.get('minutes')),note:f.get('note').trim()});saveState();closeModal();render();};}
function openBookModal(){openModal('添加书籍',`<form id="bookForm"><div class="form-group"><label>书名</label><input class="input" name="title" required></div><div class="form-group"><label>作者</label><input class="input" name="author"></div><div class="form-group"><label>状态</label><select class="select" name="status"><option>想读</option><option>在读</option><option>已读</option></select></div><div class="form-group"><label>阅读进度（0-100）</label><input class="input" type="number" name="progress" min="0" max="100" value="0"></div><button class="primary-btn">加入书单</button></form>`);$('bookForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.books.push({id:uid(),title:f.get('title').trim(),author:f.get('author').trim(),status:f.get('status'),progress:Number(f.get('progress'))});saveState();closeModal();render();};}

function tarotDashboardHtml(today,greeting){
  const draw=state.tarotHistory?.[today];
  if(!draw){
    return `<button id="dailyTarotCard" class="daily-tarot empty-tarot"><div class="tarot-mini-back"><span>✦</span></div><div class="tarot-daily-copy"><span class="tiny-label">${formatChineseDate(new Date())}</span><h2>${greeting}，抽取你的今日运势牌</h2><p>点击选择一张属于今天的塔罗牌，并记录正位或逆位。</p><strong>开始今日占卜 →</strong></div></button>`;
  }
  const card=tarotDeck.find(x=>x.id===draw.cardId), reversed=draw.position==='reversed';
  if(!card) return '';
  return `<button id="dailyTarotCard" class="daily-tarot">${tarotArtHtml(card,'tarot-mini-image',reversed)}<div class="tarot-daily-copy"><span class="tiny-label">${formatChineseDate(new Date())} · 今日运势</span><h2>${escapeHtml(card.name)} · ${reversed?'逆位':'正位'}</h2><p>${escapeHtml(reversed?card.reversed:card.upright)}</p></div></button>`;
}

function enterTarotCenter(sub='today'){ currentMain='tarot'; currentSub=sub; currentFolderId=null; render(); }
function leaveTarotCenter(){ currentMain='home'; currentSub='overview'; render(); }
function renderTarot(){
  quickAddBtn.style.display='none';
  if(currentSub==='today') renderTarotToday();
  if(currentSub==='library') renderTarotLibrary();
  if(currentSub==='history') renderTarotHistory();
}
function tarotTopBar(title,subtitle=''){
  return `<div class="tarot-center-head"><button id="leaveTarotBtn" class="tarot-back-btn">‹ 返回首页</button><div><span>PRIVATE TAROT BOOK</span><h2>${escapeHtml(title)}</h2>${subtitle?`<p>${escapeHtml(subtitle)}</p>`:''}</div></div>`;
}
function bindTarotBack(){ const b=$('leaveTarotBtn'); if(b)b.onclick=leaveTarotCenter; }
function renderTarotToday(){
  const today=formatDate(new Date()), draw=state.tarotHistory?.[today];
  if(!draw){
    appContent.innerHTML=tarotTopBar('今日塔罗','为今天选择一张牌，再慢慢读懂它。')+`<section class="tarot-reading-empty"><div class="tarot-deck-back"><span>✦</span><i>RWS</i></div><h3>今天的牌还没有揭开</h3><p>你可以按自己的实体牌抽牌结果，在这里选择对应牌与正逆位。</p><button id="chooseTodayTarot" class="primary-btn tarot-inline-btn">选择今日运势牌</button></section>`;
    bindTarotBack(); $('chooseTodayTarot').onclick=openTarotModal; return;
  }
  const card=tarotDeck.find(x=>x.id===draw.cardId); if(!card)return;
  const rev=draw.position==='reversed', d=tarotDetails[card.id]||{}, meaning=rev?(d.reversedLong||card.reversed):(d.uprightLong||card.upright);
  appContent.innerHTML=tarotTopBar('今日塔罗',formatChineseDate(new Date()))+`<article class="tarot-today-minimal">
    <section class="tarot-cover-section tarot-today-cover">
      ${tarotArtHtml(card,'tarot-detail-art',rev)}
      <div class="tarot-cover-copy"><span class="tarot-position">${rev?'逆位':'正位'}</span><h2>${escapeHtml(card.name)}</h2><h3>${escapeHtml(card.en)}</h3><p>${escapeHtml(d.summary||meaning)}</p><button id="changeTodayTarot" class="witch-link-btn cover-listen-btn">✦ 重新聆听今日讯息</button></div>
    </section>
    <section class="tarot-quick-card"><span>${rev?'今日逆位提示':'今日正位提示'}</span><p>${escapeHtml(meaning)}</p><blockquote>“${escapeHtml(d.advice||tarotAdvice(card,rev))}”</blockquote></section>
    <div class="tarot-today-actions single-action"><button id="openTodayCardLibrary" class="primary-btn witch-primary crystal-library-btn"><span class="crystal-icon">🔮</span><span>开启图鉴</span></button></div>
  </article>`;
  bindTarotBack();
  $('openTodayCardLibrary').onclick=()=>openTarotLibraryCard(card.id,draw.position);
  $('changeTodayTarot').onclick=openTarotModal;
}
function tarotDetailPageHtml(card,position='upright',isToday=false){
  const rev=position==='reversed', d=tarotDetails[card.id]||{};
  const meaning=rev?(d.reversedLong||card.reversed):(d.uprightLong||card.upright);
  const symbols=d.symbols||defaultCardSymbols(card);
  const cover=`<section class="tarot-cover-section">
      ${tarotArtHtml(card,'tarot-detail-art',rev)}
      <div class="tarot-cover-copy"><span class="tarot-position">${rev?'逆位':'正位'}</span><h2>${escapeHtml(card.name)}</h2><h3>${escapeHtml(card.en)}</h3><p>${escapeHtml(d.summary||meaning)}</p></div>
    </section>`;
  if(rev){
    return `<article class="tarot-detail-page compact-tarot-reader reversed-reader">
      ${cover}
      <section class="tarot-book-section reversed-overview"><span class="chapter-label">REVERSED VIEW</span><h2>逆位画面</h2><p class="long-reading">${escapeHtml(reversedOverview(card,d))}</p></section>
      <section class="tarot-book-section reversed-meaning"><span class="chapter-label">REVERSED MEANING</span><h2>逆位牌意</h2><p class="long-reading">${escapeHtml(meaning)}</p><div class="meaning-grid">${meaningBlocks(card,true).map(x=>`<div><small>${x[0]}</small><p>${escapeHtml(x[1])}</p></div>`).join('')}</div></section>
      <section class="tarot-quote"><span>今日提醒</span><p>“${escapeHtml(d.advice||tarotAdvice(card,true))}”</p></section>
    </article>`;
  }
  return `<article class="tarot-detail-page compact-tarot-reader upright-reader">
    ${cover}
    <section class="tarot-quick-card"><span>正位核心</span><p>${escapeHtml(meaning)}</p><blockquote>“${escapeHtml(d.advice||tarotAdvice(card,false))}”</blockquote></section>
    <section class="tarot-info-grid"><div><small>牌组</small><strong>${escapeHtml(card.group)}</strong></div><div><small>元素</small><strong>${escapeHtml(d.element||suitElement(card.group))}</strong></div><div><small>占星对应</small><strong>${escapeHtml(d.astrology||'后续牌组补充')}</strong></div><div><small>数字含义</small><strong>${escapeHtml(d.numerology||String(card.number))}</strong></div></section>
    <details class="tarot-fold" open><summary><span>01</span>整体画面</summary><div class="fold-body"><p>${escapeHtml(d.overview||`${card.name}通过人物、环境与${card.group}象征物，共同表达“${card.upright}”。`)}</p></div></details>
    <details class="tarot-fold"><summary><span>02</span>画面与象征</summary><div class="fold-body symbol-list">${symbols.map(x=>`<div><b>${escapeHtml(x[0])}</b><p>${escapeHtml(x[1])}</p></div>`).join('')}</div></details>
    ${d.colors?`<details class="tarot-fold"><summary><span>03</span>色彩语言</summary><div class="fold-body"><p>${escapeHtml(d.colors)}</p></div></details>`:''}
    <details class="tarot-fold"><summary><span>04</span>正位牌意</summary><div class="fold-body"><p class="long-reading">${escapeHtml(meaning)}</p><div class="meaning-grid">${meaningBlocks(card,false).map(x=>`<div><small>${x[0]}</small><p>${escapeHtml(x[1])}</p></div>`).join('')}</div></div></details>
  </article>`;
}
function reversedOverview(card,d){
  const base=d.overview||`${card.name}的原始牌面以人物、环境和象征物共同呈现其核心能量。`;
  return `牌面倒置后，${base} 原本清晰的重心与行动方向被翻转：上方的象征物像向下坠落，人物的站姿、手势与视线不再稳固，环境中的道路、河流、天空或建筑也更容易呈现停滞、回流或失衡。逆位并不是把每个符号逐字取反，而是观察这股核心能量为何受阻、过度、内化或延迟。`;
}
function suitElement(group){ return ({'权杖':'火元素','圣杯':'水元素','宝剑':'风元素','星币':'土元素','大阿卡纳':'综合象征'})[group]||'—'; }
function meaningBlocks(card,rev){
  const base=rev?card.reversed:card.upright;
  return [['核心',base],['感情',rev?'避免凭焦虑猜测关系，先确认真实需求与边界。':'真诚表达，并观察双方是否愿意朝同一方向投入。'],['工作／学业',rev?'检查阻力来自准备不足、节奏失衡，还是目标本身需要调整。':'把牌的核心能量转化成一个明确、可以完成的行动。'],['今日提醒',tarotAdvice(card,rev)]];
}
function tarotAdvice(card,rev){ return rev?'今天先调整节奏，不必用更大的力气重复无效的方法。':`把“${card.upright.split('、')[0]}”落实成一个小而具体的行动。`; }
function bindTarotDetailActions(cardId){}
function renderTarotLibrary(){
  appContent.innerHTML=`<div class="tarot-library-back-row"><button id="leaveTarotBtn" class="tarot-back-btn">‹ 返回首页</button></div><div class="tarot-library-tools"><input id="tarotLibrarySearch" class="input" placeholder="搜索牌名，例如：星星、权杖三…"><div class="tarot-filter-row">${['全部','大阿卡纳','权杖','圣杯','宝剑','星币'].map((x,i)=>`<button class="tarot-filter ${i===0?'active':''}" data-tarot-filter="${x}">${x}</button>`).join('')}</div></div><div id="tarotLibraryGrid" class="tarot-library-grid"></div>`;
  bindTarotBack(); let filter='全部'; const input=$('tarotLibrarySearch');
  function draw(){ const q=input.value.trim().toLowerCase(); const list=tarotDeck.filter(c=>(filter==='全部'||c.group===filter)&&(!q||`${c.name} ${c.en} ${c.group}`.toLowerCase().includes(q))); $('tarotLibraryGrid').innerHTML=list.map(c=>`<button class="tarot-library-card" data-tarot-card="${c.id}">${tarotArtHtml(c,'mini-rws-image',false)}<strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.en)}</small></button>`).join('')||'<p class="soft-empty">没有找到对应牌。</p>'; document.querySelectorAll('[data-tarot-card]').forEach(b=>b.onclick=()=>openTarotLibraryCard(b.dataset.tarotCard)); }
  input.oninput=draw; document.querySelectorAll('[data-tarot-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.tarotFilter;document.querySelectorAll('[data-tarot-filter]').forEach(x=>x.classList.toggle('active',x===b));draw();}); draw();
}
function openTarotLibraryCard(id,initialPosition='upright'){
  const card=tarotDeck.find(x=>x.id===id); if(!card)return;
  const start=initialPosition==='reversed'?'reversed':'upright';
  appContent.innerHTML=tarotTopBar(card.name,card.en)+`<div class="library-position-switch"><button class="${start==='upright'?'active':''}" data-position-view="upright">正位</button><button class="${start==='reversed'?'active':''}" data-position-view="reversed">逆位</button></div><div id="libraryCardDetail">${tarotDetailPageHtml(card,start)}</div>`;
  bindTarotBack();
  document.querySelectorAll('[data-position-view]').forEach(b=>b.onclick=()=>{
    document.querySelectorAll('[data-position-view]').forEach(x=>x.classList.toggle('active',x===b));
    $('libraryCardDetail').innerHTML=tarotDetailPageHtml(card,b.dataset.positionView);
  });
}
function openLearningTopic(i){ const t=tarotLearningTopics[i]; openModal(t.title,`<div class="topic-reader"><div class="topic-icon">${t.icon}</div><p>${escapeHtml(t.desc)}</p><p>这一专题将在后续内容版本中扩展成完整章节。目前已先建立入口与阅读结构。</p></div>`); }
function renderTarotHistory(){
  const allEntries=Object.entries(state.tarotHistory||{}).sort((a,b)=>b[0].localeCompare(a[0]));
  const years=[...new Set(allEntries.map(([date])=>date.slice(0,4)))].sort((a,b)=>b.localeCompare(a));
  const currentYear=String(new Date().getFullYear());
  if(!window.tarotStatsYear || !years.includes(window.tarotStatsYear)) window.tarotStatsYear=years.includes(currentYear)?currentYear:(years[0]||currentYear);
  const year=window.tarotStatsYear;
  const entries=allEntries.filter(([date])=>date.startsWith(year+'-'));
  const upright=entries.filter(([,d])=>d.position!=='reversed').length;
  const reversed=entries.length-upright;
  const uprightPct=entries.length?Math.round(upright/entries.length*100):0;
  const groupOrder=['大阿卡纳','权杖','圣杯','宝剑','星币'];
  const groupCounts=Object.fromEntries(groupOrder.map(g=>[g,0]));
  const cardCounts={};
  entries.forEach(([,d])=>{
    const c=tarotDeck.find(x=>x.id===d.cardId); if(!c)return;
    groupCounts[c.group]=(groupCounts[c.group]||0)+1;
    cardCounts[c.id]=(cardCounts[c.id]||0)+1;
  });
  const topCards=Object.entries(cardCounts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,5);
  const distinct=Object.keys(cardCounts).length;
  const maxGroup=Math.max(1,...Object.values(groupCounts));
  const yearOptions=(years.length?years:[currentYear]).map(y=>`<option value="${y}" ${y===year?'selected':''}>${y} 年</option>`).join('');
  const statsHtml=`<div class="history-toolbar"><select id="tarotStatsYear" class="select">${yearOptions}</select></div>
    <section class="annual-stats">
      <div class="stats-hero"><div><small>YEARLY TAROT</small><strong>${entries.length}</strong><span>${year} 年记录天数</span></div><div class="orientation-ring" style="--upright:${uprightPct}%"><b>${uprightPct}%</b><span>正位</span></div></div>
      <div class="stats-mini-grid"><div><b>${upright}</b><span>正位</span></div><div><b>${reversed}</b><span>逆位</span></div><div><b>${distinct}</b><span>不同牌面</span></div><div><b>${topCards[0]?.[1]||0}</b><span>最高频次数</span></div></div>
      <div class="suit-bars">${groupOrder.map(g=>`<div><span>${g}</span><i><em style="width:${Math.round((groupCounts[g]||0)/maxGroup*100)}%"></em></i><b>${groupCounts[g]||0}</b></div>`).join('')}</div>
      <div class="top-cards"><h3>年度高频牌</h3>${topCards.length?topCards.map(([id,count],i)=>{const c=tarotDeck.find(x=>x.id===id);return c?`<button data-stat-card="${id}"><span>${i+1}</span>${tarotArtHtml(c,'stats-card-image',false)}<div><strong>${escapeHtml(c.name)}</strong><small>出现 ${count} 次</small></div></button>`:''}).join(''):'<p class="soft-empty">今年还没有足够的抽牌记录。</p>'}</div>
    </section>`;
  const historyHtml=`<h3 class="history-section-title">每日记录</h3><div class="tarot-history-list">${entries.length?entries.map(([date,d])=>{const c=tarotDeck.find(x=>x.id===d.cardId);return c?`<div class="tarot-history-row-wrap"><button class="tarot-history-row" data-history-date="${date}"><div class="history-date"><b>${date.slice(5).replace('-','月')}日</b><small>${date.slice(0,4)}</small></div>${tarotArtHtml(c,'history-card-image',d.position==='reversed')}<div><strong>${escapeHtml(c.name)} · ${d.position==='reversed'?'逆位':'正位'}</strong><p>${escapeHtml(d.position==='reversed'?c.reversed:c.upright)}</p></div></button><button class="history-delete-btn" data-delete-history="${date}" aria-label="删除 ${date} 的记录">删除</button></div>`:''}).join(''):emptyHtml('☾',`${year} 年还没有每日塔罗记录。`)}</div>`;
  appContent.innerHTML=tarotTopBar('历史统计','回看这一年里，命运曾递给你的牌。')+statsHtml+historyHtml;
  bindTarotBack();
  const yearSelect=$('tarotStatsYear'); if(yearSelect)yearSelect.onchange=()=>{window.tarotStatsYear=yearSelect.value;renderTarotHistory();};
  document.querySelectorAll('[data-stat-card]').forEach(b=>b.onclick=()=>openTarotLibraryCard(b.dataset.statCard));
  document.querySelectorAll('[data-history-date]').forEach(b=>b.onclick=()=>{const d=state.tarotHistory[b.dataset.historyDate],c=tarotDeck.find(x=>x.id===d.cardId);if(!c)return;appContent.innerHTML=tarotTopBar(`${b.dataset.historyDate} · ${c.name}`,'历史运势牌')+tarotDetailPageHtml(c,d.position);bindTarotBack();});
  document.querySelectorAll('[data-delete-history]').forEach(b=>b.onclick=e=>{e.stopPropagation();const date=b.dataset.deleteHistory;const d=state.tarotHistory?.[date],c=d&&tarotDeck.find(x=>x.id===d.cardId);if(!d)return;if(confirm(`确定删除 ${date} 的「${c?.name||'塔罗牌'}」记录吗？`)){delete state.tarotHistory[date];saveState();renderTarotHistory();}});
}


function getBackupMeta(){
  try{return JSON.parse(localStorage.getItem(BACKUP_META_KEY)||'{}');}catch{return {};}
}
function backupStatusText(){
  const last=getBackupMeta().lastExportedAt;
  if(!last)return {text:'还没有保存过工作台存档',tone:'warn'};
  const date=new Date(last),days=Math.floor((Date.now()-date.getTime())/86400000);
  if(days<=0)return {text:'上次存档：今天',tone:'ok'};
  if(days===1)return {text:'上次存档：昨天',tone:'ok'};
  return {text:`上次存档：${days} 天前`,tone:days>=30?'warn':'ok'};
}
function normalizeImportedState(incoming){
  const base=structuredClone(defaultData);
  const merged={...base,...incoming};
  merged.todos={...base.todos,...(incoming.todos||{})};if(!Array.isArray(merged.todos.edit))merged.todos.edit=[];if(Array.isArray(incoming.todos?.parcel)){const ids=new Set(merged.todos.edit.map(x=>x.id));merged.todos.edit.push(...incoming.todos.parcel.filter(x=>!ids.has(x.id)));}delete merged.todos.parcel;
  merged.scheduleTodos={...base.scheduleTodos,...(incoming.scheduleTodos||{})};
  merged.folders=(merged.folders||[]).map(f=>({...f,notes:(f.notes||[]).map(n=>({pinned:false,tags:[],...n}))}));
  merged.schedule=(merged.schedule||[]).map(x=>({color:'rose',pinned:false,tags:[],...x}));
  merged.tarotHistory=incoming.tarotHistory||{};
  return merged;
}
function openBackupModal(){
  const status=backupStatusText();
  openModal('工作台存档',`<div class="backup-panel workspace-backup-panel">
    <div class="backup-status-card ${status.tone}"><span class="backup-cloud">☁</span><div><strong>${status.text}</strong><p>${status.tone==='warn'?'建议现在保存一份新的存档。':'你的工作台已有近期存档。'}</p></div></div>
    <p class="soft-note">存档会包含自媒体待办、文案文件夹、日程、健康、阅读记录，以及全部塔罗历史与统计。</p>
    <button id="exportAllData" class="primary-btn">⬆ 导出整个工作台</button>
    <label class="import-label">⬇ 恢复整个工作台<input id="importAllData" type="file" accept="application/json,.json"></label>
    <p class="soft-note backup-warning">恢复存档会覆盖当前设备里的数据。恢复前，建议先导出一份当前存档作为保险。</p>
  </div>`);
  $('exportAllData').onclick=()=>{
    const now=new Date();
    const payload={app:'personal-workbench',version:APP_VERSION,storageKey:STORAGE_KEY,exportedAt:now.toISOString(),data:state};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download=`Personal-Workbench-v${APP_VERSION}-${formatDate(now)}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
    localStorage.setItem(BACKUP_META_KEY,JSON.stringify({lastExportedAt:now.toISOString(),version:APP_VERSION}));
    closeModal();
    setTimeout(()=>alert('工作台已经安全保存。建议把文件存入 iCloud Drive。'),80);
  };
  $('importAllData').onchange=async e=>{
    const file=e.target.files?.[0]; if(!file)return;
    try{
      const parsed=JSON.parse(await file.text());
      const incoming=parsed?.data||parsed;
      if(!incoming || typeof incoming!=='object' || !incoming.todos || !incoming.scheduleTodos || !Array.isArray(incoming.folders)) throw new Error('invalid');
      if(!confirm('恢复后，当前工作台中的全部数据会被这个存档覆盖。确定继续吗？'))return;
      state=normalizeImportedState(incoming);
      saveState();
      localStorage.setItem(BACKUP_META_KEY,JSON.stringify({lastImportedAt:new Date().toISOString(),sourceVersion:parsed?.version||'unknown'}));
      closeModal();render();alert('工作台存档已恢复。');
    }catch(err){alert('无法读取这个存档文件。请确认它是由个人工作台导出的 JSON 文件。');}
  };
}

function openTarotModal(){
  const today=formatDate(new Date()), saved=state.tarotHistory?.[today], selected=saved?.cardId||tarotDeck[0].id, position=saved?.position||'upright';
  openModal('今日塔罗',`<form id="tarotForm"><div class="tarot-picker-preview" id="tarotPreview"></div><div class="form-group"><label>选择牌组</label><select class="select" id="tarotGroup"><option value="all">全部 78 张</option><option>大阿卡纳</option><option>权杖</option><option>圣杯</option><option>宝剑</option><option>星币</option></select></div><div class="form-group"><label>选择塔罗牌</label><select class="select" id="tarotCardSelect"></select></div><div class="position-choice"><label><input type="radio" name="position" value="upright" ${position==='upright'?'checked':''}><span>☀ 正位</span></label><label><input type="radio" name="position" value="reversed" ${position==='reversed'?'checked':''}><span>☾ 逆位</span></label></div><button class="primary-btn">保存为今日运势牌</button></form><p class="tarot-note">每日按日期单独保存；第二天会自动显示新的空白占卜卡。</p>`);
  const group=$('tarotGroup'), select=$('tarotCardSelect'), preview=$('tarotPreview');
  function fill(){const list=group.value==='all'?tarotDeck:tarotDeck.filter(x=>x.group===group.value);select.innerHTML=list.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${c.group} · ${c.name} / ${c.en}</option>`).join('');if(!list.some(x=>x.id===select.value))select.value=list[0]?.id||'';update();}
  function update(){const card=tarotDeck.find(x=>x.id===select.value), pos=document.querySelector('input[name="position"]:checked')?.value||'upright';if(!card)return;const rev=pos==='reversed';preview.innerHTML=`${tarotArtHtml(card,'tarot-large-image',rev)}<div><span class="tarot-position">${rev?'逆位':'正位'}</span><h3>${escapeHtml(card.name)}</h3><p>${escapeHtml(rev?card.reversed:card.upright)}</p></div>`;}
  group.onchange=fill;select.onchange=update;document.querySelectorAll('input[name="position"]').forEach(x=>x.onchange=update);fill();
  $('tarotForm').onsubmit=e=>{e.preventDefault();state.tarotHistory=state.tarotHistory||{};state.tarotHistory[today]={cardId:select.value,position:new FormData(e.target).get('position'),savedAt:new Date().toISOString()};saveState();closeModal();render();};
}
function roman(n){if(n===0)return '0';const vals=[[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];let out='';for(const [v,c] of vals)while(n>=v){out+=c;n-=v;}return out;}

function openSearchModal(){openModal('全局搜索',`<div class="search-wrap"><input id="globalSearchInput" class="input search-input" placeholder="搜索待办、日程、文案、书籍或标签…"><div id="searchResults" class="search-results"><p class="soft-empty">输入关键词开始搜索。</p></div></div>`);const input=$('globalSearchInput');input.oninput=()=>renderSearchResults(input.value);setTimeout(()=>input.focus(),50);}
function renderSearchResults(q){
  q=q.trim().toLowerCase();const box=$('searchResults');if(!q){box.innerHTML='<p class="soft-empty">输入关键词开始搜索。</p>';return;}
  const results=[];
  Object.entries(state.todos).forEach(([type,list])=>list.forEach(x=>{if(matches(x,q))results.push({kind:'待办',title:x.title,sub:x.note||type,go:`media|${type}`});}));
  state.schedule.forEach(x=>{if(matches(x,q))results.push({kind:'日程',title:x.title,sub:`${x.date} ${x.time||'全天'} · ${(x.tags||[]).join(' ')}`,go:'schedule|month',scheduleId:x.id,date:x.date});});
  state.folders.forEach(f=>(f.notes||[]).forEach(n=>{if(matches(n,q))results.push({kind:'文案',title:n.title,sub:`${f.name} · ${(n.tags||[]).join(' ')}`,folderId:f.id,noteId:n.id});}));
  state.books.forEach(x=>{if(matches(x,q))results.push({kind:'书籍',title:x.title,sub:x.author||x.status,go:'reading|booklist'});});
  box.innerHTML=results.length?results.slice(0,50).map((r,i)=>`<button class="search-result" data-search-index="${i}"><span>${r.kind}</span><div><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.sub||'')}</small></div></button>`).join(''):'<p class="soft-empty">没有找到相关内容。</p>';
  box.querySelectorAll('[data-search-index]').forEach(btn=>btn.onclick=()=>{const r=results[Number(btn.dataset.searchIndex)];closeModal();if(r.folderId){currentMain='media';currentSub='copy';currentFolderId=r.folderId;render();setTimeout(()=>openNoteEditor(r.folderId,r.noteId),0);}else if(r.scheduleId){currentMain='schedule';currentSub='month';scheduleMonthDate=startOfMonth(new Date(r.date+'T00:00:00'));selectedMonthDate=r.date;render();setTimeout(()=>openScheduleModal(r.scheduleId),0);}else{[currentMain,currentSub]=r.go.split('|');render();}});
}
function matches(x,q){return [x.title,x.note,x.content,x.author,...(x.tags||[])].filter(Boolean).join(' ').toLowerCase().includes(q);}

function enablePointerSort(container,onOrder){
  if(!container)return;
  let item=null,pointerId=null,startY=0,lastY=0,moved=false,holdTimer=null;
  const clear=()=>{clearTimeout(holdTimer);holdTimer=null;};
  const finish=()=>{
    clear();
    if(!item)return;
    item.classList.remove('dragging');
    document.body.classList.remove('is-sorting');
    const ids=[...container.querySelectorAll('.sortable-item')].map(x=>x.dataset.sortId);
    const shouldSave=moved;
    item=null;pointerId=null;moved=false;
    if(shouldSave)onOrder(ids);
  };
  container.querySelectorAll('[data-drag-handle]').forEach(handle=>{
    handle.onpointerdown=e=>{
      if(item)return;
      const candidate=handle.closest('.sortable-item');if(!candidate)return;
      pointerId=e.pointerId;startY=lastY=e.clientY;moved=false;
      holdTimer=setTimeout(()=>{item=candidate;item.classList.add('dragging');document.body.classList.add('is-sorting');handle.setPointerCapture?.(pointerId);navigator.vibrate?.(18);},140);
      e.preventDefault();
    };
    handle.onpointermove=e=>{
      if(e.pointerId!==pointerId)return;
      lastY=e.clientY;
      if(!item){if(Math.abs(lastY-startY)>10)clear();return;}
      if(Math.abs(lastY-startY)>3)moved=true;
      const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.sortable-item');
      if(target&&target!==item&&target.parentElement===container){
        const r=target.getBoundingClientRect();
        container.insertBefore(item,e.clientY<r.top+r.height/2?target:target.nextSibling);
      }
      const edge=56;
      if(e.clientY<edge)window.scrollBy(0,-10);else if(e.clientY>window.innerHeight-edge)window.scrollBy(0,10);
      e.preventDefault();
    };
    handle.onpointerup=e=>{if(e.pointerId===pointerId)finish();};
    handle.onpointercancel=e=>{if(e.pointerId===pointerId)finish();};
    handle.onlostpointercapture=finish;
  });
}

function openModal(title,html){modalTitle.textContent=title;modalBody.innerHTML=html;modal.classList.remove('hidden');}
function closeModal(){modal.classList.add('hidden');modalBody.innerHTML='';}
function emptyHtml(icon,text){return `<div class="empty"><div class="empty-icon">${icon}</div><div>${text}</div></div>`;}
function tagHtml(tags=[]){return tags?.length?`<div class="tag-row">${tags.map(t=>`<span>#${escapeHtml(t)}</span>`).join('')}</div>`:'';}
function parseTags(v=''){return [...new Set(String(v).split(/[,，]/).map(x=>x.trim()).filter(Boolean))].slice(0,8);}
function updateTags(tags){state.tags=[...new Set([...(state.tags||[]),...tags])];}
function pad(n){return String(n).padStart(2,'0');}
function formatDate(d){return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;}
function startOfMonth(d){return new Date(d.getFullYear(),d.getMonth(),1);}
function startOfWeek(d){const x=new Date(d);const day=(x.getDay()+6)%7;x.setDate(x.getDate()-day);x.setHours(0,0,0,0);return x;}
function getWeekKey(d){return formatDate(startOfWeek(d));}
function formatShortDate(v){const d=new Date(v+'T00:00:00');return `${d.getMonth()+1}月${d.getDate()}日`;}
function formatChineseDate(d){return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日 · ${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][d.getDay()]}`;}
function completedLast(list=[]){return [...list].sort((a,b)=>Number(a.done)-Number(b.done));}
function sortSchedule(a,b){return (a.date+(a.time||'99:99')).localeCompare(b.date+(b.time||'99:99'));}
function escapeHtml(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function escapeAttr(v=''){return escapeHtml(v);}

if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js');
render();
